CREATE OR REPLACE FUNCTION public.act_guild_mission_v2(p_actor uuid, p_mission uuid, p_action text, p_note text, p_request uuid, p_expected_attempt integer)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE m public.guild_missions; p public.guild_mission_progress; a public.guild_mission_attempts; v_attempt integer;
BEGIN
 SELECT * INTO m FROM public.guild_missions WHERE id=p_mission FOR UPDATE;
 PERFORM guild_ops.actor(p_actor,m.guild_id);
 IF p_request IS NULL OR p_action IS NULL OR p_action NOT IN ('start','submit') OR p_expected_attempt IS NULL OR p_expected_attempt<0 THEN RAISE EXCEPTION 'Invalid action'; END IF;
 IF m.audience='selected' AND NOT p_actor=ANY(m.target_traveler_ids) THEN RAISE EXCEPTION 'Not eligible' USING ERRCODE='42501'; END IF;
 SELECT * INTO p FROM public.guild_mission_progress WHERE mission_id=p_mission AND traveler_id=p_actor FOR UPDATE;
 IF p_action='submit' THEN
   SELECT * INTO a FROM public.guild_mission_attempts WHERE mission_id=p_mission AND traveler_id=p_actor AND request_id=p_request;
   IF FOUND THEN IF a.note IS DISTINCT FROM btrim(p_note) THEN RAISE EXCEPTION 'Submission key reused'; END IF; RETURN coalesce(a.decision,'pending_approval'); END IF;
 END IF;
 IF m.status<>'published' OR (m.starts_at IS NOT NULL AND m.starts_at>clock_timestamp()) OR (m.due_at IS NOT NULL AND m.due_at<=clock_timestamp()) THEN RAISE EXCEPTION 'Mission not available'; END IF;
 IF p_action='start' THEN
   IF p.status='started' THEN RETURN 'started'; END IF;
   IF p.status IS NOT NULL AND p.status NOT IN ('available','rejected','changes_requested') THEN RAISE EXCEPTION 'Mission already submitted'; END IF;
   INSERT INTO public.guild_mission_progress(mission_id,traveler_id,status,started_at) VALUES(p_mission,p_actor,'started',clock_timestamp()) ON CONFLICT(mission_id,traveler_id) DO UPDATE SET status='started',started_at=coalesce(public.guild_mission_progress.started_at,clock_timestamp());
   RETURN 'started';
 END IF;
 IF p.status IS DISTINCT FROM 'started' OR p.submission_revision<>p_expected_attempt OR length(btrim(coalesce(p_note,''))) NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'Submission unavailable or evidence missing'; END IF;
 v_attempt:=p.submission_revision+1;
 INSERT INTO public.guild_mission_attempts(mission_id,traveler_id,revision,request_id,note) VALUES(p_mission,p_actor,v_attempt,p_request,btrim(p_note));
 UPDATE public.guild_mission_progress SET status='pending_approval',completion_note=btrim(p_note),submitted_at=clock_timestamp(),submission_revision=v_attempt,review_note=NULL,approved_at=NULL,approved_by_traveler_id=NULL WHERE id=p.id;
 RETURN 'pending_approval';
END $function$

CREATE OR REPLACE FUNCTION public.add_coins(p_traveler_id uuid, p_amount integer)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  resulting_coins integer;
BEGIN
  IF p_amount <= 0 THEN
    RAISE EXCEPTION 'Amount must be positive' USING ERRCODE = '22023';
  END IF;

  UPDATE public.wallets
  SET coins = coins + p_amount
  WHERE traveler_id = p_traveler_id
  RETURNING coins INTO resulting_coins;

  IF resulting_coins IS NULL THEN
    RAISE EXCEPTION 'Wallet not found' USING ERRCODE = 'P0002';
  END IF;

  RETURN resulting_coins;
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_guild_mission_reward(p_mission_id uuid, p_traveler_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  tier text;
  xp_value integer;
  coin_value integer;
  chest_type_value text;
  chest_quantity_value integer := 1;
  previous_xp integer;
  next_xp integer;
  level_bonus integer := 0;
BEGIN
  SELECT reward_tier INTO tier FROM public.guild_missions WHERE id = p_mission_id;
  xp_value := CASE tier WHEN 'normal' THEN 80 WHEN 'great' THEN 240 WHEN 'epic' THEN 480 WHEN 'extraordinary' THEN 720 ELSE NULL END;
  coin_value := CASE tier WHEN 'normal' THEN 25 WHEN 'great' THEN 100 WHEN 'epic' THEN 220 WHEN 'extraordinary' THEN 360 ELSE NULL END;
  chest_type_value := CASE tier WHEN 'normal' THEN 'common' WHEN 'great' THEN 'uncommon' WHEN 'epic' THEN 'rare' WHEN 'extraordinary' THEN 'epic' ELSE NULL END;
  IF xp_value IS NULL OR chest_type_value IS NULL OR chest_quantity_value <> 1 THEN
    RAISE EXCEPTION 'Invalid reward tier' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.guild_reward_claims(mission_id, traveler_id, reward_tier, xp_awarded, coins_awarded)
  VALUES (p_mission_id, p_traveler_id, tier, xp_value, coin_value)
  ON CONFLICT (mission_id, traveler_id) DO NOTHING;
  IF NOT FOUND THEN RETURN false; END IF;

  SELECT xp INTO previous_xp FROM public.travelers WHERE id = p_traveler_id FOR UPDATE;
  next_xp := previous_xp + xp_value;
  IF previous_xp < 200 AND next_xp >= 200 THEN level_bonus := 10; END IF;
  UPDATE public.travelers
  SET xp = next_xp,
      level = LEAST(50, GREATEST(1, floor((1 + sqrt(1 + next_xp::numeric / 25)) / 2)::integer))
  WHERE id = p_traveler_id;
  UPDATE public.wallets SET coins = coins + coin_value + level_bonus WHERE traveler_id = p_traveler_id;
  PERFORM public.grant_traveler_chest(
    p_traveler_id,
    chest_type_value,
    'guild_mission',
    'guild_mission:' || p_mission_id::text || ':' || p_traveler_id::text
  );
  RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.arena_authority_v3(p_user uuid, p_traveler uuid, p_operation text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE t public.travelers%ROWTYPE; b economy_private.battles%ROWTYPE;
 r public.chest_operations%ROWTYPE; c jsonb; version_value text; ids jsonb;
 context_value jsonb; quota integer; won boolean; result_value jsonb; old_xp integer;
BEGIN
 IF jsonb_typeof(p_payload) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Invalid payload' USING ERRCODE='22023'; END IF;
 -- One lock order for cross-Traveler starter claims, starts, commands and payout.
 PERFORM 1 FROM auth.users WHERE id=p_user AND NOT coalesce(is_anonymous,false) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Account denied' USING ERRCODE='42501'; END IF;
 SELECT * INTO t FROM public.travelers WHERE id=p_traveler AND user_id=p_user FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Ownership denied' USING ERRCODE='42501'; END IF;
 IF p_operation='collection' THEN RETURN economy_private.collection(p_user,t.id); END IF;
 IF p_operation='starter' THEN
  -- Program identity is stable across catalog revisions and Traveler creation.
  SELECT * INTO r FROM public.chest_operations WHERE identity_key='arena-starter-v1:'||p_user;
  IF FOUND THEN RETURN to_jsonb(r); END IF;
  IF (SELECT count(DISTINCT version) FROM economy_private.card_catalog WHERE starter AND revoked_at IS NULL)<>1 THEN RAISE EXCEPTION 'Approved starter unavailable' USING ERRCODE='42501'; END IF;
  SELECT min(version) INTO version_value FROM economy_private.card_catalog WHERE starter AND revoked_at IS NULL;
  SELECT jsonb_agg(id ORDER BY id) INTO ids FROM economy_private.card_catalog WHERE version=version_value AND starter AND revoked_at IS NULL;
  IF jsonb_array_length(ids) IS DISTINCT FROM 7 OR (SELECT count(DISTINCT definition->>'action') FROM economy_private.card_catalog WHERE version=version_value AND starter AND revoked_at IS NULL)<>7
  THEN RAISE EXCEPTION 'Approved starter unavailable' USING ERRCODE='42501'; END IF;
  INSERT INTO public.chest_operations(traveler_id,operation_key,operation_type,source,identity_key,account_id,rewards)
   VALUES(t.id,'arena-starter-v1','card-starter','approved-starter','arena-starter-v1:'||p_user,p_user,
   jsonb_build_object('schemaVersion',2,'catalogVersion',version_value,'cardIds',ids)) RETURNING * INTO r;
  INSERT INTO public.inventory(traveler_id,item_id,quantity,metadata,card_receipt_id,card_version)
   SELECT t.id,c.id,1,jsonb_build_object('source','approved-starter'),r.id,c.version
   FROM economy_private.card_catalog c WHERE c.version=version_value AND c.starter AND c.revoked_at IS NULL;
  RETURN to_jsonb(r);
 END IF;
 IF p_operation='revoke-card' THEN
  IF length(coalesce(p_payload->>'reason','')) NOT BETWEEN 1 AND 500 OR length(coalesce(p_payload->>'reviewRef','')) NOT BETWEEN 1 AND 160 THEN RAISE EXCEPTION 'Reviewed reason required'; END IF;
  SELECT * INTO r FROM public.chest_operations WHERE traveler_id=t.id AND operation_key='card-revoke:'||(p_payload->>'cardId');
  IF FOUND THEN
   IF r.rewards->>'reviewRef' IS DISTINCT FROM p_payload->>'reviewRef' OR r.rewards->>'reason' IS DISTINCT FROM p_payload->>'reason' THEN RAISE EXCEPTION 'Revocation conflict' USING ERRCODE='40001'; END IF;
   RETURN to_jsonb(r);
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.inventory WHERE traveler_id=t.id AND item_id=p_payload->>'cardId' AND card_receipt_id IS NOT NULL) THEN RAISE EXCEPTION 'Card missing'; END IF;
  INSERT INTO public.chest_operations(traveler_id,operation_key,operation_type,source,account_id,rewards)
   VALUES(t.id,'card-revoke:'||(p_payload->>'cardId'),'card-revocation','reviewed-revocation',p_user,jsonb_build_object('cardId',p_payload->>'cardId','reason',p_payload->>'reason','reviewRef',p_payload->>'reviewRef')) RETURNING * INTO r;
  UPDATE public.inventory SET card_revoked_at=now(),card_revocation_receipt_id=r.id WHERE traveler_id=t.id AND item_id=p_payload->>'cardId';
  RETURN to_jsonb(r);
 END IF;
 IF p_operation='context' THEN
  RETURN economy_private.base_authority(p_user,t.id,'context','{}');
 ELSIF p_operation='purchase' THEN
  IF t.economic_verified_at IS NULL THEN RAISE EXCEPTION 'Legacy reconciliation required' USING ERRCODE='42501'; END IF;
  RETURN economy_private.base_authority(p_user,t.id,'purchase',p_payload);
 ELSIF p_operation='start' THEN
  IF t.economic_verified_at IS NULL THEN RAISE EXCEPTION 'Legacy reconciliation required' USING ERRCODE='42501'; END IF;
  SELECT * INTO b FROM economy_private.battles WHERE traveler_id=t.id AND request_id=(p_payload->>'requestId')::uuid;
  IF FOUND THEN
   IF b.request_digest IS DISTINCT FROM p_payload->>'digest' THEN RAISE EXCEPTION 'Request conflict' USING ERRCODE='40001'; END IF;
   RETURN to_jsonb(b);
  END IF;
  IF p_payload->>'mode' NOT IN ('arena-v3','tower-v3') OR p_payload->>'requestId' IS NULL THEN RAISE EXCEPTION 'Invalid mode'; END IF;
  c:=economy_private.collection(p_user,t.id); ids:=p_payload->'ids';
  IF jsonb_typeof(ids) IS DISTINCT FROM 'array' OR jsonb_array_length(ids)<>7 OR (SELECT count(DISTINCT value) FROM jsonb_array_elements(ids))<>7 THEN RAISE EXCEPTION 'Invalid deck' USING ERRCODE='22023'; END IF;
  IF (SELECT count(*) FROM jsonb_array_elements(c) e WHERE ids ? (e->'card'->>'id'))<>7 THEN RAISE EXCEPTION 'Card ownership denied' USING ERRCODE='42501'; END IF;
  SELECT min(e->>'version') INTO version_value FROM jsonb_array_elements(c) e WHERE ids ? (e->'card'->>'id');
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(c) e WHERE ids ? (e->'card'->>'id') AND e->>'version'<>version_value) THEN RAISE EXCEPTION 'Mixed catalog'; END IF;
  context_value:=economy_private.base_authority(p_user,t.id,'context','{}');
  IF p_payload->'context' IS DISTINCT FROM context_value THEN RAISE EXCEPTION 'Context changed' USING ERRCODE='40001'; END IF;
  IF p_payload->>'mode'='tower-v3' THEN
   SELECT coalesce(max(floor),0)+1 INTO quota FROM economy_private.battles WHERE traveler_id=t.id AND mode='tower-v3'
    AND tower_version='permanent-v1' AND settled_at IS NOT NULL AND reward->>'outcome'='victory';
   IF (p_payload->>'floor')::integer IS DISTINCT FROM quota OR quota>7 OR p_payload->>'towerVersion' IS DISTINCT FROM 'permanent-v1' THEN RAISE EXCEPTION 'Tower order denied' USING ERRCODE='42501'; END IF;
  END IF;
  INSERT INTO economy_private.battles(traveler_id,seed,player,opponent,mode,context,catalog_version,rules_version,cards,floor,tower_version,request_id,request_digest)
  VALUES(t.id,('x'||encode(extensions.gen_random_bytes(4),'hex'))::bit(32)::bigint,p_payload->'player',p_payload->'opponent',p_payload->>'mode',context_value,version_value,
   p_payload->>'rulesVersion',(SELECT jsonb_agg(e->'card' ORDER BY e->'card'->>'id') FROM jsonb_array_elements(c) e WHERE ids ? (e->'card'->>'id')),
   (p_payload->>'floor')::integer,p_payload->>'towerVersion',(p_payload->>'requestId')::uuid,p_payload->>'digest') RETURNING * INTO b;
  RETURN to_jsonb(b);
 ELSIF p_operation='latest' THEN
  SELECT * INTO b FROM economy_private.battles WHERE traveler_id=t.id AND mode=p_payload->>'mode' ORDER BY created_at DESC,id DESC LIMIT 1;
  RETURN CASE WHEN b.id IS NULL THEN 'null'::jsonb ELSE to_jsonb(b) END;
 ELSIF p_operation IN ('battle','commit') THEN
  SELECT * INTO b FROM economy_private.battles WHERE traveler_id=t.id AND id=(p_payload->>'battleId')::uuid AND mode IN ('arena-v3','tower-v3') FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Battle ownership denied' USING ERRCODE='42501'; END IF;
  IF p_operation='battle' THEN RETURN to_jsonb(b); END IF;
  IF b.settled_at IS NOT NULL OR b.revision IS DISTINCT FROM (p_payload->>'revision')::integer OR (p_payload->>'commandId')::uuid=ANY(b.command_ids)
   THEN RAISE EXCEPTION 'Stale or finished battle' USING ERRCODE='40001'; END IF;
  IF p_payload->>'commandId' IS NULL OR jsonb_typeof(p_payload->'state') IS DISTINCT FROM 'object' OR p_payload->'state'->>'id' IS DISTINCT FROM b.id::text
   THEN RAISE EXCEPTION 'Invalid server state'; END IF;
  IF p_payload->>'rulesVersion' IS DISTINCT FROM b.rules_version THEN RAISE EXCEPTION 'Rules unavailable' USING ERRCODE='40001'; END IF;
  c:=economy_private.collection(p_user,t.id);
  IF (SELECT count(*) FROM jsonb_array_elements(c) e WHERE e->>'version'=b.catalog_version AND EXISTS(SELECT 1 FROM jsonb_array_elements(b.cards) selected WHERE selected->>'id'=e->'card'->>'id'))<>7 THEN RAISE EXCEPTION 'Card ownership revoked' USING ERRCODE='42501'; END IF;
  -- The trusted TypeScript server alone supplies the derived state. CAS commits
  -- the accepted round, card consumption, result, receipt and credits together.
  UPDATE economy_private.battles SET state=p_payload->'state',revision=revision+1,
   command_ids=array_append(command_ids,(p_payload->>'commandId')::uuid),commands=commands||jsonb_build_array(p_payload->'command') WHERE id=b.id RETURNING * INTO b;
  IF b.state->>'status'='finished' THEN
   won:=coalesce(b.state->>'winnerId'=t.id::text,false);
   IF b.mode='arena-v3' THEN
    SELECT count(*) INTO quota FROM economy_private.battles WHERE traveler_id=t.id AND mode IN ('arena-v3','card','classic')
      AND opponent->>'id'=b.opponent->>'id' AND settled_at>=date_trunc('day',now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' AND reward->>'rewarded'='true';
    result_value:=jsonb_build_object('xp',CASE WHEN won AND quota<3 THEN 8 ELSE 0 END,'coins',CASE WHEN won AND quota<3 THEN 3 ELSE 0 END,
     'rewarded',won AND quota<3,'reason',CASE WHEN NOT won THEN 'defeat' WHEN quota>=3 THEN 'daily-limit' ELSE 'victory' END,
     'outcome',CASE WHEN won THEN 'victory' ELSE 'defeat' END,'status','confirmed',
     'levelBonusCoins',CASE WHEN won AND quota<3 AND t.xp<200 AND t.xp+8>=200 THEN 10 ELSE 0 END);
    IF won AND quota<3 THEN
     old_xp:=t.xp;
     UPDATE public.travelers SET xp=xp+8,level=least(50,greatest(1,floor((1+sqrt(1+(xp+8)::numeric/25))/2)::integer)) WHERE id=t.id;
     UPDATE public.wallets SET coins=coins+3+CASE WHEN old_xp<200 AND old_xp+8>=200 THEN 10 ELSE 0 END WHERE traveler_id=t.id;
     IF NOT FOUND THEN RAISE EXCEPTION 'Wallet missing'; END IF;
    END IF;
   ELSE
    result_value:=jsonb_build_object('xp',0,'coins',0,'rewarded',false,'reason','tower-economy-unapproved','status','blocked',
     'outcome',CASE WHEN won THEN 'victory' ELSE 'defeat' END,'towerVersion',b.tower_version,'floor',b.floor);
   END IF;
   INSERT INTO public.chest_operations(traveler_id,operation_key,operation_type,source,account_id,rewards)
    VALUES(t.id,'battle:'||b.id,CASE WHEN b.mode='arena-v3' THEN 'arena-result' ELSE 'tower-result' END,'server-battle-v3',p_user,result_value) RETURNING * INTO r;
   UPDATE economy_private.battles SET settled_at=now(),reward=result_value,receipt_id=r.id WHERE id=b.id RETURNING * INTO b;
  END IF;
  RETURN to_jsonb(b);
 ELSIF p_operation='tower' THEN
  SELECT coalesce(max(floor),0)+1 INTO quota FROM economy_private.battles WHERE traveler_id=t.id AND mode='tower-v3' AND tower_version='permanent-v1' AND reward->>'outcome'='victory' AND settled_at IS NOT NULL;
  RETURN jsonb_build_object('nextFloor',quota,'version','permanent-v1','rewardStatus','blocked');
 ELSE RAISE EXCEPTION 'Operation denied' USING ERRCODE='42501'; END IF;
END $function$

CREATE OR REPLACE FUNCTION public.claim_chest_reward(p_traveler_id uuid, p_reward_key text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF NOT public.owns_traveler(p_traveler_id) THEN RAISE EXCEPTION 'Traveler not owned' USING ERRCODE = '42501'; END IF;
  IF p_reward_key = 'phase:garden-choice' THEN
    RETURN public.grant_traveler_chest(p_traveler_id, 'common', 'phase_completion', p_reward_key);
  END IF;
  RAISE EXCEPTION 'Unknown chest reward' USING ERRCODE = '22023';
END $function$

CREATE OR REPLACE FUNCTION public.complete_story(p_traveler_id uuid, p_story_id text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_definition public.story_definitions; v_progress public.story_progress; v_steps text[];
BEGIN
  -- Identity is the existing Auth account; no leader role or guild membership.
  PERFORM 1 FROM public.travelers t JOIN auth.users u ON u.id=t.user_id
    WHERE t.id=p_traveler_id AND t.user_id=auth.uid() AND u.is_anonymous IS FALSE FOR UPDATE OF t;
  IF NOT FOUND THEN RAISE EXCEPTION 'Story access denied' USING ERRCODE='42501'; END IF;
  SELECT * INTO v_definition FROM public.story_definitions WHERE id=p_story_id FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Unknown story'; END IF;
  SELECT * INTO v_progress FROM public.story_progress WHERE traveler_id=p_traveler_id AND story_id=p_story_id;
  IF v_progress.completed_at IS NOT NULL THEN RETURN false; END IF;
  IF NOT (v_definition.content_ready AND v_definition.video_ready AND v_definition.reward_ready) THEN
    RAISE EXCEPTION 'Story dependencies pending';
  END IF;
  IF EXISTS (SELECT 1 FROM public.story_definitions d WHERE d.narrative_order < v_definition.narrative_order
    AND NOT EXISTS (SELECT 1 FROM public.story_progress p WHERE p.traveler_id=p_traveler_id AND p.story_id=d.id AND p.completed_at IS NOT NULL)) THEN
    RAISE EXCEPTION 'Previous story incomplete';
  END IF;
  SELECT array_agg(step) INTO v_steps FROM story_private.step_receipts
    WHERE traveler_id=p_traveler_id AND story_id=p_story_id AND revision=v_definition.revision;
  IF v_steps IS NULL OR NOT (v_steps @> v_definition.required_steps)
    OR NOT COALESCE(v_progress.video_completed,false) OR v_progress.reward_receipt IS NULL THEN
    RAISE EXCEPTION 'Story requirements incomplete';
  END IF;
  UPDATE public.story_progress SET completed_at=clock_timestamp() WHERE traveler_id=p_traveler_id AND story_id=p_story_id;
  RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.create_guild_mission(p_creator_traveler_id uuid, p_title text, p_description text, p_mission_type text, p_bible_reference text, p_bible_url text, p_completion_mode text, p_reward_tier text, p_starts_at timestamp with time zone, p_due_at timestamp with time zone, p_publish boolean DEFAULT false, p_metadata jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE creator_guild_id uuid; new_mission_id uuid;
BEGIN
  IF NOT public.owns_traveler(p_creator_traveler_id) THEN RAISE EXCEPTION 'Creator not owned' USING ERRCODE = '42501'; END IF;
  SELECT guild_id INTO creator_guild_id FROM public.guild_members WHERE traveler_id = p_creator_traveler_id AND role = 'leader' AND status = 'active';
  IF creator_guild_id IS NULL THEN RAISE EXCEPTION 'Leader role required' USING ERRCODE = '42501'; END IF;
  IF p_mission_type NOT IN ('bible_reading','lesson','quiz','practical_activity','individual_challenge','collective_challenge','special_mission','journey_gate') OR p_completion_mode NOT IN ('self_complete','leader_approval') OR p_reward_tier NOT IN ('normal','great','epic','extraordinary') THEN RAISE EXCEPTION 'Invalid mission domain value' USING ERRCODE = '22023'; END IF;
  INSERT INTO public.guild_missions(guild_id, created_by_traveler_id, title, description, mission_type, bible_reference, bible_url, completion_mode, requires_leader_approval, reward_tier, status, starts_at, due_at, metadata, published_at)
  VALUES (creator_guild_id, p_creator_traveler_id, btrim(p_title), nullif(btrim(coalesce(p_description,'')),''), p_mission_type, nullif(btrim(coalesce(p_bible_reference,'')),''), nullif(btrim(coalesce(p_bible_url,'')),''), p_completion_mode, p_completion_mode = 'leader_approval', p_reward_tier, CASE WHEN p_publish THEN 'published' ELSE 'draft' END, p_starts_at, p_due_at, p_metadata, CASE WHEN p_publish THEN now() ELSE NULL END)
  RETURNING id INTO new_mission_id;
  RETURN new_mission_id;
END $function$

CREATE OR REPLACE FUNCTION public.create_guild(p_leader_traveler_id uuid, p_name text, p_description text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE new_guild_id uuid;
BEGIN
  IF NOT public.owns_traveler(p_leader_traveler_id) THEN RAISE EXCEPTION 'Traveler not owned' USING ERRCODE = '42501'; END IF;
  IF char_length(btrim(p_name)) NOT BETWEEN 2 AND 60 OR char_length(coalesce(p_description, '')) > 500 THEN RAISE EXCEPTION 'Invalid guild data' USING ERRCODE = '22023'; END IF;
  IF EXISTS (SELECT 1 FROM public.guild_members WHERE traveler_id = p_leader_traveler_id AND status = 'active') THEN RAISE EXCEPTION 'Traveler already belongs to a guild' USING ERRCODE = '23505'; END IF;
  INSERT INTO public.guilds(name, description, created_by_user_id, leader_traveler_id)
  VALUES (btrim(p_name), nullif(btrim(coalesce(p_description, '')), ''), auth.uid(), p_leader_traveler_id) RETURNING id INTO new_guild_id;
  INSERT INTO public.guild_members(guild_id, traveler_id, role, status) VALUES (new_guild_id, p_leader_traveler_id, 'leader', 'active');
  RETURN new_guild_id;
END $function$

CREATE OR REPLACE FUNCTION ebd_ops.command(p_actor uuid, p_action text, p_id uuid, p_revision integer, p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_guild uuid; v_role text; l public.guild_lessons; a public.guild_ebd_activities;
 ans public.guild_ebd_answers; att public.guild_ebd_attendance; et public.guild_ebd_teachers;
 v_teacher uuid; v_target uuid; v_targets uuid[]; v_state text; v_revision integer; v_count integer;
 v_item jsonb; v_options jsonb; v_key integer; v_choice integer; v_snapshot jsonb;
BEGIN
 IF p_actor IS NULL OR p_id IS NULL OR p_action IS NULL OR p_revision IS NULL OR p_revision<0
 OR p_data IS NULL OR jsonb_typeof(p_data)<>'object' OR length(p_data::text)>60000 THEN RAISE EXCEPTION 'Invalid EBD request'; END IF;
 SELECT guild_id INTO v_guild FROM public.guild_members WHERE traveler_id=p_actor AND status='active';
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_guild::text,83));
 v_role:=guild_ops.actor(p_actor,v_guild);
 -- Serialize EBD commands per Guilda, including grant revocations/member eligibility.
 PERFORM 1 FROM public.guilds WHERE id=v_guild FOR UPDATE;
 IF p_action='teacher' THEN
  PERFORM guild_ops.actor(p_actor,v_guild,true);
  PERFORM 1 FROM public.guild_members WHERE guild_id=v_guild AND traveler_id=p_id AND status='active' AND role<>'leader' FOR SHARE;
  IF NOT FOUND OR jsonb_typeof(p_data->'active') IS DISTINCT FROM 'boolean'
   OR jsonb_typeof(p_data->'publish') IS DISTINCT FROM 'boolean' OR jsonb_typeof(p_data->'attend') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'Teacher unavailable'; END IF;
  SELECT * INTO et FROM public.guild_ebd_teachers WHERE guild_id=v_guild AND traveler_id=p_id FOR UPDATE;
  IF coalesce(et.revision,0)<>p_revision THEN RAISE EXCEPTION 'EBD conflict' USING ERRCODE='40001'; END IF;
  INSERT INTO public.guild_ebd_teachers VALUES(v_guild,p_id,(p_data->>'active')::boolean,(p_data->>'publish')::boolean,(p_data->>'attend')::boolean,p_revision+1,clock_timestamp())
   ON CONFLICT(guild_id,traveler_id) DO UPDATE SET active=excluded.active,can_publish=excluded.can_publish,can_attend=excluded.can_attend,revision=excluded.revision,updated_at=excluded.updated_at;
  INSERT INTO public.guild_ebd_history(guild_id,actor_id,action,entity_id,revision,snapshot) VALUES(v_guild,p_actor,'teacher',p_id,p_revision+1,p_data);
  RETURN jsonb_build_object('id',p_id,'revision',p_revision+1);
 ELSIF p_action='lesson' THEN
  v_teacher:=(p_data->>'teacherId')::uuid;
  IF v_role<>'leader' AND (v_teacher IS DISTINCT FROM p_actor OR NOT EXISTS(SELECT 1 FROM public.guild_ebd_teachers WHERE guild_id=v_guild AND traveler_id=p_actor AND active)) THEN RAISE EXCEPTION 'EBD access denied' USING ERRCODE='42501'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.guild_members gm JOIN public.guilds g ON g.id=gm.guild_id
   LEFT JOIN public.guild_ebd_teachers t ON t.guild_id=gm.guild_id AND t.traveler_id=gm.traveler_id
   WHERE gm.guild_id=v_guild AND gm.traveler_id=v_teacher AND gm.status='active' AND ((gm.role='leader' AND g.leader_traveler_id=v_teacher) OR t.active)) THEN RAISE EXCEPTION 'Teacher unavailable'; END IF;
  IF jsonb_typeof(p_data->'targetIds') IS DISTINCT FROM 'array' OR jsonb_array_length(p_data->'targetIds')>100
   OR jsonb_typeof(p_data->'materials') IS DISTINCT FROM 'array' OR jsonb_array_length(p_data->'materials')>20
   OR coalesce(p_data->>'audience','') NOT IN ('all','selected')
   OR length(btrim(coalesce(p_data->>'title',''))) NOT BETWEEN 2 AND 100
   OR length(btrim(coalesce(p_data->>'theme',''))) NOT BETWEEN 2 AND 100
   OR length(coalesce(p_data->>'description',''))>2000 OR length(coalesce(p_data->>'content',''))>10000
   OR length(coalesce(p_data->>'reference',''))>100 OR length(coalesce(p_data->>'objectives',''))>2000
   OR coalesce(p_data->>'rewardTier','') NOT IN ('','normal','great','epic','extraordinary') THEN RAISE EXCEPTION 'Invalid lesson'; END IF;
  SELECT coalesce(array_agg(value::uuid),'{}') INTO v_targets FROM jsonb_array_elements_text(p_data->'targetIds');
  IF (p_data->>'audience'='selected' AND cardinality(v_targets)=0) OR (p_data->>'audience'='all' AND cardinality(v_targets)>0)
   OR EXISTS(SELECT 1 FROM unnest(v_targets) t WHERE NOT EXISTS(SELECT 1 FROM public.guild_members WHERE guild_id=v_guild AND traveler_id=t AND status='active')) THEN RAISE EXCEPTION 'Audience unavailable'; END IF;
  FOR v_item IN SELECT value FROM jsonb_array_elements(p_data->'materials') LOOP
   IF jsonb_typeof(v_item) IS DISTINCT FROM 'object' OR coalesce(v_item->>'kind','') NOT IN ('link','image','pdf','text','reference')
    OR length(btrim(coalesce(v_item->>'title',''))) NOT BETWEEN 1 AND 100 OR length(btrim(coalesce(v_item->>'value',''))) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Invalid material'; END IF;
   -- References only: never fetch/embed remote files or render HTML; no credentials/ports/local hosts.
   IF v_item->>'kind' IN ('link','image','pdf') AND
    (length(v_item->>'value')>500 OR (v_item->>'value') !~ '^https://[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?(\.[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?)*\.[A-Za-z]{2,}(/[A-Za-z0-9/._~!$&()*+,;=:@%?#-]*)?$'
     OR (v_item->>'value') ~* '^https://([^/]*\.)?(localhost|local|internal|invalid|test|example)(/|$)' OR (v_item->>'value') ~* '^https://[^/]*\.(local|internal|invalid|test|example)(/|$)') THEN RAISE EXCEPTION 'Unsafe material URL'; END IF;
  END LOOP;
  SELECT * INTO l FROM public.guild_lessons WHERE id=p_id FOR UPDATE;
  IF FOUND THEN
   IF l.guild_id<>v_guild OR NOT ebd_ops.manager(p_actor,p_id) THEN RAISE EXCEPTION 'EBD access denied' USING ERRCODE='42501'; END IF;
   IF p_revision=0 AND l.creation_hash=md5(p_data::text) THEN RETURN jsonb_build_object('id',p_id,'revision',l.ebd_revision); END IF;
   IF l.status<>'draft' OR l.ebd_revision<>p_revision THEN RAISE EXCEPTION 'EBD conflict' USING ERRCODE='40001'; END IF;
   UPDATE public.guild_lessons SET title=btrim(p_data->>'title'),theme=btrim(p_data->>'theme'),introduction=coalesce(p_data->>'description',''),content=coalesce(p_data->>'content',''),bible_reference=coalesce(p_data->>'reference',''),scheduled_at=nullif(p_data->>'scheduledAt','')::timestamptz,teacher_id=v_teacher,audience=p_data->>'audience',target_ids=v_targets,materials=p_data->'materials',objectives=coalesce(p_data->>'objectives',''),reward_tier=nullif(p_data->>'rewardTier',''),ebd_revision=ebd_revision+1 WHERE id=p_id;
  ELSE
   IF p_revision<>0 THEN RAISE EXCEPTION 'EBD conflict' USING ERRCODE='40001'; END IF;
   INSERT INTO public.guild_lessons(id,guild_id,created_by_traveler_id,teacher_id,title,theme,introduction,content,bible_reference,scheduled_at,audience,target_ids,materials,objectives,reward_tier,creation_hash)
    VALUES(p_id,v_guild,p_actor,v_teacher,btrim(p_data->>'title'),btrim(p_data->>'theme'),coalesce(p_data->>'description',''),coalesce(p_data->>'content',''),coalesce(p_data->>'reference',''),nullif(p_data->>'scheduledAt','')::timestamptz,p_data->>'audience',v_targets,p_data->'materials',coalesce(p_data->>'objectives',''),nullif(p_data->>'rewardTier',''),md5(p_data::text));
  END IF;
  SELECT to_jsonb(x),x.ebd_revision INTO v_snapshot,v_revision FROM public.guild_lessons x WHERE id=p_id;
  INSERT INTO public.guild_ebd_history(guild_id,lesson_id,actor_id,action,entity_id,revision,snapshot) VALUES(v_guild,p_id,p_actor,'lesson_saved',p_id,v_revision,v_snapshot);
 ELSIF p_action='state' THEN
  SELECT * INTO l FROM public.guild_lessons WHERE id=p_id FOR UPDATE;
  IF l.guild_id IS DISTINCT FROM v_guild OR NOT ebd_ops.manager(p_actor,p_id,'publish') THEN RAISE EXCEPTION 'EBD access denied' USING ERRCODE='42501'; END IF;
  v_state:=p_data->>'state';
  IF l.ebd_revision<>p_revision THEN RAISE EXCEPTION 'EBD conflict' USING ERRCODE='40001'; END IF;
  IF v_state IS NULL OR NOT ((l.status='draft' AND v_state IN ('scheduled','published','archived')) OR (l.status='scheduled' AND v_state IN ('draft','published','archived')) OR (l.status='published' AND v_state='closed') OR (l.status IN ('closed','completed','cancelled') AND v_state='archived')) THEN RAISE EXCEPTION 'Invalid EBD state'; END IF;
  IF v_state IN ('scheduled','published') AND (length(btrim(l.content))=0 OR l.scheduled_at IS NULL) THEN RAISE EXCEPTION 'Lesson needs content and date'; END IF;
  UPDATE public.guild_lessons SET status=v_state,ebd_revision=ebd_revision+1,published_at=CASE WHEN v_state='published' THEN clock_timestamp() ELSE published_at END,completed_at=CASE WHEN v_state='closed' THEN clock_timestamp() ELSE completed_at END WHERE id=p_id;
  SELECT to_jsonb(x),x.ebd_revision INTO v_snapshot,v_revision FROM public.guild_lessons x WHERE id=p_id;
  INSERT INTO public.guild_ebd_history(guild_id,lesson_id,actor_id,action,entity_id,revision,snapshot) VALUES(v_guild,p_id,p_actor,'state',p_id,v_revision,v_snapshot);
 ELSIF p_action='activity' THEN
  SELECT * INTO l FROM public.guild_lessons WHERE id=(p_data->>'lessonId')::uuid FOR UPDATE;
  IF l.guild_id IS DISTINCT FROM v_guild OR NOT ebd_ops.manager(p_actor,l.id) OR l.status<>'draft' THEN RAISE EXCEPTION 'EBD access denied' USING ERRCODE='42501'; END IF;
  IF jsonb_typeof(p_data->'options') IS DISTINCT FROM 'array' OR jsonb_array_length(p_data->'options')>6
   OR coalesce(p_data->>'kind','') NOT IN ('choice','open','reflective','in_person','homework')
   OR coalesce(p_data->>'criterion','') NOT IN ('participation','correct','manual') THEN RAISE EXCEPTION 'Invalid activity'; END IF;
  v_options:=p_data->'options'; v_key:=nullif(p_data->>'answerKey','')::integer;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(v_options) x WHERE jsonb_typeof(x)<>'string' OR length(btrim(x#>>'{}')) NOT BETWEEN 1 AND 300)
   OR (p_data->>'kind'='choice' AND p_data->>'criterion'='manual') THEN RAISE EXCEPTION 'Invalid choices'; END IF;
  SELECT * INTO a FROM public.guild_ebd_activities WHERE id=p_id FOR UPDATE;
  IF FOUND THEN
   IF a.lesson_id<>l.id THEN RAISE EXCEPTION 'EBD access denied'; END IF;
   IF p_revision=0 AND a.creation_hash=md5(p_data::text) THEN RETURN jsonb_build_object('id',p_id,'revision',a.revision); END IF;
   IF a.revision<>p_revision THEN RAISE EXCEPTION 'EBD conflict' USING ERRCODE='40001'; END IF;
   UPDATE public.guild_ebd_activities SET title=btrim(p_data->>'title'),kind=p_data->>'kind',prompt=p_data->>'prompt',options=v_options,answer_key=v_key,deadline=nullif(p_data->>'deadline','')::timestamptz,attempt_limit=(p_data->>'attemptLimit')::integer,criterion=p_data->>'criterion',revision=revision+1 WHERE id=p_id;
  ELSE
   IF p_revision<>0 THEN RAISE EXCEPTION 'EBD conflict' USING ERRCODE='40001'; END IF;
   IF (SELECT count(*) FROM public.guild_ebd_activities WHERE lesson_id=l.id)>=20 THEN RAISE EXCEPTION 'Activity limit reached'; END IF;
   INSERT INTO public.guild_ebd_activities(id,lesson_id,title,kind,prompt,options,answer_key,deadline,attempt_limit,criterion,creation_hash)
    VALUES(p_id,l.id,btrim(p_data->>'title'),p_data->>'kind',p_data->>'prompt',v_options,v_key,nullif(p_data->>'deadline','')::timestamptz,(p_data->>'attemptLimit')::integer,p_data->>'criterion',md5(p_data::text));
  END IF;
  SELECT to_jsonb(x),x.revision INTO v_snapshot,v_revision FROM public.guild_ebd_activities x WHERE id=p_id;
  INSERT INTO public.guild_ebd_history(guild_id,lesson_id,actor_id,action,entity_id,revision,snapshot) VALUES(v_guild,l.id,p_actor,'activity_saved',p_id,v_revision,v_snapshot);
 ELSIF p_action='submit' THEN
  SELECT * INTO a FROM public.guild_ebd_activities WHERE id=(p_data->>'activityId')::uuid FOR UPDATE;
  SELECT * INTO l FROM public.guild_lessons WHERE id=a.lesson_id;
  IF l.guild_id IS DISTINCT FROM v_guild OR NOT ebd_ops.eligible(p_actor,l.id) THEN RAISE EXCEPTION 'EBD access denied' USING ERRCODE='42501'; END IF;
  v_choice:=nullif(p_data->>'choice','')::integer;
  SELECT * INTO ans FROM public.guild_ebd_answers WHERE id=p_id;
  IF FOUND THEN
   IF ans.traveler_id=p_actor AND ans.activity_id=a.id AND ans.response=btrim(p_data->>'response') AND ans.choice IS NOT DISTINCT FROM v_choice THEN RETURN jsonb_build_object('id',p_id,'revision',ans.revision); END IF;
   RAISE EXCEPTION 'Submission key conflict';
  END IF;
  IF l.status<>'published' OR (a.deadline IS NOT NULL AND a.deadline<=clock_timestamp()) THEN RAISE EXCEPTION 'Activity closed'; END IF;
  SELECT count(*) INTO v_count FROM public.guild_ebd_answers WHERE activity_id=a.id AND traveler_id=p_actor;
  IF v_count<>p_revision OR v_count>=a.attempt_limit OR EXISTS(SELECT 1 FROM public.guild_ebd_answers WHERE activity_id=a.id AND traveler_id=p_actor AND status IN ('completed','pending')) THEN RAISE EXCEPTION 'Attempt unavailable'; END IF;
  IF (a.kind='choice' AND (v_choice IS NULL OR v_choice<0 OR v_choice>=jsonb_array_length(a.options))) OR (a.kind<>'choice' AND v_choice IS NOT NULL) THEN RAISE EXCEPTION 'Invalid answer'; END IF;
  v_state:=CASE WHEN a.kind<>'choice' THEN 'pending' WHEN a.criterion='participation' OR v_choice=a.answer_key THEN 'completed' ELSE 'revise' END;
  INSERT INTO public.guild_ebd_answers(id,activity_id,traveler_id,attempt,response,choice,status,evaluated_at)
   VALUES(p_id,a.id,p_actor,v_count+1,btrim(p_data->>'response'),v_choice,v_state,CASE WHEN a.kind='choice' THEN clock_timestamp() END);
  v_revision:=1;
 ELSIF p_action='grade' THEN
  SELECT * INTO ans FROM public.guild_ebd_answers WHERE id=p_id FOR UPDATE;
  SELECT * INTO a FROM public.guild_ebd_activities WHERE id=ans.activity_id;
  SELECT * INTO l FROM public.guild_lessons WHERE id=a.lesson_id;
  IF l.guild_id IS DISTINCT FROM v_guild OR NOT ebd_ops.manager(p_actor,l.id) OR EXISTS(SELECT 1 FROM public.travelers WHERE id=ans.traveler_id AND user_id=auth.uid()) THEN RAISE EXCEPTION 'EBD access denied' USING ERRCODE='42501'; END IF;
  IF ans.revision<>p_revision THEN RAISE EXCEPTION 'EBD conflict' USING ERRCODE='40001'; END IF;
  IF ans.status<>'pending' OR coalesce(p_data->>'status','') NOT IN ('completed','revise') THEN RAISE EXCEPTION 'Answer already evaluated'; END IF;
  UPDATE public.guild_ebd_answers SET status=p_data->>'status',feedback=coalesce(p_data->>'feedback',''),reviewer_id=p_actor,evaluated_at=clock_timestamp(),revision=revision+1 WHERE id=p_id;
  SELECT to_jsonb(x),x.revision INTO v_snapshot,v_revision FROM public.guild_ebd_answers x WHERE id=p_id;
  INSERT INTO public.guild_ebd_history(guild_id,lesson_id,actor_id,action,entity_id,revision,snapshot) VALUES(v_guild,l.id,p_actor,'grade',p_id,v_revision,v_snapshot);
 ELSIF p_action='attendance' THEN
  SELECT * INTO l FROM public.guild_lessons WHERE id=p_id FOR UPDATE;
  v_target:=(p_data->>'travelerId')::uuid;
  IF l.guild_id IS DISTINCT FROM v_guild OR NOT ebd_ops.manager(p_actor,p_id,'attend') OR l.status NOT IN ('published','closed','completed') THEN RAISE EXCEPTION 'EBD access denied' USING ERRCODE='42501'; END IF;
  PERFORM 1 FROM public.guild_members WHERE guild_id=v_guild AND traveler_id=v_target AND status='active' FOR SHARE;
  IF NOT FOUND OR (l.audience='selected' AND NOT v_target=ANY(l.target_ids)) THEN RAISE EXCEPTION 'Student unavailable'; END IF;
  SELECT * INTO att FROM public.guild_ebd_attendance WHERE lesson_id=p_id AND traveler_id=v_target FOR UPDATE;
  IF coalesce(att.revision,0)<>p_revision THEN RAISE EXCEPTION 'EBD conflict' USING ERRCODE='40001'; END IF;
  INSERT INTO public.guild_ebd_attendance VALUES(p_id,v_target,p_data->>'status',coalesce(p_data->>'reason',''),p_revision+1,p_actor,clock_timestamp())
   ON CONFLICT(lesson_id,traveler_id) DO UPDATE SET status=excluded.status,reason=excluded.reason,revision=excluded.revision,marked_by=excluded.marked_by,updated_at=excluded.updated_at;
  SELECT to_jsonb(x) INTO v_snapshot FROM public.guild_ebd_attendance x WHERE lesson_id=p_id AND traveler_id=v_target;
  v_revision:=p_revision+1;
  INSERT INTO public.guild_ebd_history(guild_id,lesson_id,actor_id,action,entity_id,revision,snapshot) VALUES(v_guild,p_id,p_actor,'attendance',v_target,v_revision,jsonb_build_object('before',to_jsonb(att),'after',v_snapshot));
 ELSE RAISE EXCEPTION 'Unknown EBD action'; END IF;
 IF p_action IN ('submit','grade') THEN
  INSERT INTO public.guild_ebd_reward_pending(lesson_id,traveler_id,activity_id,answer_id,tier,criterion)
   SELECT l.id,x.traveler_id,a.id,x.id,l.reward_tier,a.criterion FROM public.guild_ebd_answers x
   WHERE x.id=p_id AND x.status='completed' AND l.reward_tier IS NOT NULL ON CONFLICT(lesson_id,traveler_id) DO NOTHING;
 END IF;
 RETURN jsonb_build_object('id',p_id,'revision',v_revision);
END $function$

CREATE OR REPLACE FUNCTION ebd_ops.workspace(p_actor uuid, p_offset integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE g uuid; r text; ids uuid[]; total integer; teacher boolean;
BEGIN
 IF p_offset IS NULL OR p_offset<0 OR p_offset>100000 THEN RAISE EXCEPTION 'Invalid EBD page'; END IF;
 SELECT guild_id INTO g FROM public.guild_members WHERE traveler_id=p_actor AND status='active';
 r:=guild_ops.actor(p_actor,g);
 teacher:=r='leader' OR EXISTS(SELECT 1 FROM public.guild_ebd_teachers WHERE guild_id=g AND traveler_id=p_actor AND active);
 SELECT count(*) INTO total FROM public.guild_lessons l WHERE guild_id=g AND (ebd_ops.manager(p_actor,l.id) OR ebd_ops.eligible(p_actor,l.id));
 SELECT coalesce(array_agg(id),'{}') INTO ids FROM (SELECT id FROM public.guild_lessons l WHERE guild_id=g AND (ebd_ops.manager(p_actor,l.id) OR ebd_ops.eligible(p_actor,l.id)) ORDER BY created_at DESC,id LIMIT 20 OFFSET p_offset) page;
 RETURN jsonb_build_object('version',1,'guildId',g,'leader',r='leader','teacher',teacher,'total',total,
  'lessons',coalesce((SELECT jsonb_agg(to_jsonb(l)||jsonb_build_object('canEdit',ebd_ops.manager(p_actor,l.id),'canPublish',ebd_ops.manager(p_actor,l.id,'publish'),'canAttend',ebd_ops.manager(p_actor,l.id,'attend')) ORDER BY created_at DESC,id) FROM public.guild_lessons l WHERE id=ANY(ids)),'[]'::jsonb),
  'activities',coalesce((SELECT jsonb_agg((to_jsonb(a)-'answer_key'-'creation_hash')||CASE WHEN ebd_ops.manager(p_actor,a.lesson_id) OR EXISTS(SELECT 1 FROM public.guild_ebd_answers x WHERE x.activity_id=a.id AND x.traveler_id=p_actor AND (x.status='completed' OR (x.status='revise' AND x.attempt>=a.attempt_limit))) THEN jsonb_build_object('answer_key',a.answer_key) ELSE '{}'::jsonb END) FROM public.guild_ebd_activities a WHERE lesson_id=ANY(ids)),'[]'::jsonb),
  'answers',coalesce((SELECT jsonb_agg(to_jsonb(x)||jsonb_build_object('traveler_name',t.name) ORDER BY submitted_at DESC) FROM public.guild_ebd_answers x JOIN public.guild_ebd_activities a ON a.id=x.activity_id JOIN public.travelers t ON t.id=x.traveler_id WHERE a.lesson_id=ANY(ids) AND (x.traveler_id=p_actor OR ebd_ops.manager(p_actor,a.lesson_id))),'[]'::jsonb),
  'attendance',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM public.guild_ebd_attendance x WHERE lesson_id=ANY(ids) AND (x.traveler_id=p_actor OR ebd_ops.manager(p_actor,x.lesson_id))),'[]'::jsonb),
  'rewards',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM public.guild_ebd_reward_pending x WHERE lesson_id=ANY(ids) AND (x.traveler_id=p_actor OR ebd_ops.manager(p_actor,x.lesson_id))),'[]'::jsonb),
  'members',CASE WHEN teacher THEN coalesce((SELECT jsonb_agg(jsonb_build_object('id',t.id,'name',t.name,'leader',gm.role='leader')) FROM public.guild_members gm JOIN public.travelers t ON t.id=gm.traveler_id WHERE gm.guild_id=g AND gm.status='active'),'[]'::jsonb) ELSE '[]'::jsonb END,
  'teachers',CASE WHEN teacher THEN coalesce((SELECT jsonb_agg(to_jsonb(t)) FROM public.guild_ebd_teachers t WHERE guild_id=g AND (r='leader' OR traveler_id=p_actor OR active)),'[]'::jsonb) ELSE '[]'::jsonb END,
  'history',coalesce((SELECT jsonb_agg(to_jsonb(h)) FROM (SELECT id,lesson_id,actor_id,action,entity_id,revision,created_at FROM public.guild_ebd_history h WHERE guild_id=g AND (r='leader' OR (lesson_id=ANY(ids) AND ebd_ops.manager(p_actor,lesson_id))) ORDER BY id DESC LIMIT 100) h),'[]'::jsonb));
END $function$

CREATE OR REPLACE FUNCTION economy_private.authority(p_user_id uuid, p_traveler_id uuid, p_operation text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE t public.travelers%ROWTYPE; j economy_private.journeys%ROWTYPE; prior_digest text;
 result_value jsonb; reward_key_value text; coin_value integer:=0; xp_value integer:=0; item_value text; old_xp integer; new_xp integer; fresh boolean:=false;
BEGIN
 SELECT * INTO t FROM public.travelers WHERE id=p_traveler_id AND user_id=p_user_id FOR UPDATE;
 IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=p_user_id AND NOT coalesce(is_anonymous,false)) THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF;
 IF p_operation IN ('journey-context','journey-commit') THEN
   SELECT * INTO j FROM economy_private.journeys WHERE traveler_id=t.id FOR UPDATE;
   IF NOT FOUND THEN RAISE EXCEPTION 'Journey not initialized' USING ERRCODE='P0002'; END IF;
   IF p_operation='journey-context' THEN RETURN jsonb_build_object('state',j.state,'revision',j.revision); END IF;
   IF p_payload->>'operationId' IS NULL OR p_payload->>'digest' IS NULL OR length(p_payload->>'digest')<>64 THEN RAISE EXCEPTION 'Invalid operation' USING ERRCODE='22023'; END IF;
   SELECT digest INTO prior_digest FROM economy_private.journey_operations WHERE traveler_id=t.id AND operation_id=(p_payload->>'operationId')::uuid;
   IF FOUND THEN
     IF prior_digest IS DISTINCT FROM p_payload->>'digest' THEN RAISE EXCEPTION 'Operation payload conflict' USING ERRCODE='22023'; END IF;
     RETURN jsonb_build_object('progress',j.state->'progress','revision',j.revision,'duplicate',true);
   END IF;
   IF (p_payload->>'revision')::integer IS DISTINCT FROM j.revision THEN RAISE EXCEPTION 'Stale journey' USING ERRCODE='40001'; END IF;
   IF jsonb_typeof(p_payload->'state') IS DISTINCT FROM 'object' OR octet_length((p_payload->'state')::text)>131072 THEN RAISE EXCEPTION 'Invalid state' USING ERRCODE='22023'; END IF;
   reward_key_value:=p_payload->>'rewardKey';
   IF reward_key_value IS NOT NULL THEN
     coin_value:=CASE reward_key_value WHEN 'coins-grove' THEN 8 WHEN 'coins-river' THEN 12 WHEN 'chest-path' THEN 10 WHEN 'chest-hidden' THEN 18 WHEN 'hidden-corner' THEN 7 WHEN 'wind-pattern' THEN 5 WHEN 'garden-equipment' THEN 0 WHEN 'phase:garden-choice' THEN 30 ELSE NULL END;
     IF coin_value IS NULL THEN RAISE EXCEPTION 'Invalid reward source' USING ERRCODE='22023'; END IF;
     INSERT INTO economy_private.journey_rewards(traveler_id,reward_key) VALUES(t.id,reward_key_value) ON CONFLICT DO NOTHING;
     fresh:=FOUND;
     IF fresh THEN
       IF reward_key_value='phase:garden-choice' THEN xp_value:=120;item_value:='wisdom-amulet'; END IF;
       IF reward_key_value='garden-equipment' THEN item_value:='traveler-helmet-rare'; END IF;
       old_xp:=t.xp;new_xp:=old_xp+xp_value;
       UPDATE public.travelers SET xp=new_xp,level=least(50,greatest(1,floor((1+sqrt(1+new_xp::numeric/25))/2)::integer)) WHERE id=t.id;
       UPDATE public.wallets SET coins=coins+coin_value+CASE WHEN old_xp<200 AND new_xp>=200 THEN 10 ELSE 0 END WHERE traveler_id=t.id;
       IF NOT FOUND THEN RAISE EXCEPTION 'Wallet missing'; END IF;
       IF item_value IS NOT NULL THEN INSERT INTO public.inventory(traveler_id,item_id,quantity,metadata) VALUES(t.id,item_value,1,jsonb_build_object('source',reward_key_value)) ON CONFLICT(traveler_id,item_id) DO NOTHING; END IF;
       IF reward_key_value='phase:garden-choice' THEN PERFORM public.grant_traveler_chest(t.id,'common','phase_completion','phase:garden-choice'); END IF;
     END IF;
   END IF;
   UPDATE economy_private.journeys SET revision=revision+1,state=p_payload->'state' WHERE traveler_id=t.id RETURNING * INTO j;
   UPDATE public.travelers SET journey_progress=coalesce(journey_progress,'{}')||(j.state->'progress')||CASE WHEN j.state->'progress'->>'gardenCompleted'='true' AND coalesce(t.journey_progress->>'guildId','')<>'' AND t.journey_progress->>'guildChallengeStatus'='locked' THEN jsonb_build_object('guildChallengeStatus','available') ELSE '{}'::jsonb END WHERE id=t.id;
   INSERT INTO economy_private.journey_operations(traveler_id,operation_id,digest) VALUES(t.id,(p_payload->>'operationId')::uuid,p_payload->>'digest');
   RETURN jsonb_build_object('progress',j.state->'progress','revision',j.revision,'duplicate',false,'rewardGranted',fresh);
 END IF;
 result_value:=economy_private.base_authority(p_user_id,p_traveler_id,p_operation,p_payload);
 IF p_operation='start' THEN
   IF coalesce(p_payload->>'mode','card') NOT IN ('card','classic') THEN RAISE EXCEPTION 'Invalid mode' USING ERRCODE='22023'; END IF;
   UPDATE economy_private.battles SET mode=coalesce(p_payload->>'mode','card') WHERE id=(result_value->>'id')::uuid;
 END IF;
 IF p_operation IN ('start','battle') THEN SELECT result_value||jsonb_build_object('mode',mode) INTO result_value FROM economy_private.battles WHERE id=(result_value->>'id')::uuid; END IF;
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION economy_private.base_authority(p_user_id uuid, p_traveler_id uuid, p_operation text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  t public.travelers%ROWTYPE;
  b economy_private.battles%ROWTYPE;
  result_value jsonb;
  price_value integer;
  prior_xp integer;
  next_xp integer;
  new_level integer;
  quota integer;
  balance integer;
  won boolean;
BEGIN
  IF p_user_id IS NULL OR p_traveler_id IS NULL OR p_operation IS NULL OR p_payload IS NULL
     OR jsonb_typeof(p_payload) <> 'object' THEN
    RAISE EXCEPTION 'Invalid operation' USING ERRCODE = '22023';
  END IF;
  -- Serializes every Arena reward and purchase for this owner; unrelated owners do not block each other.
  SELECT * INTO t FROM public.travelers WHERE id=p_traveler_id AND user_id=p_user_id FOR UPDATE;
  IF NOT FOUND OR NOT EXISTS (SELECT 1 FROM auth.users WHERE id=p_user_id AND NOT coalesce(is_anonymous,false)) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501';
  END IF;
  IF p_operation = 'context' THEN
    RETURN jsonb_build_object('name',t.name,'xp',t.xp,
      'coins',(SELECT coins FROM public.wallets WHERE traveler_id=t.id),
      'attributes',(SELECT jsonb_build_object('life',base_life,'strength',base_strength,'defense',base_defense,'wisdom',base_wisdom)
         FROM public.traveler_stats WHERE traveler_id=t.id),
      'inventory',coalesce((SELECT jsonb_agg(jsonb_build_object('item_id',item_id,'quantity',quantity)) FROM public.inventory WHERE traveler_id=t.id),'[]'::jsonb),
      'equipped',coalesce((SELECT jsonb_object_agg(slot,item_id) FROM public.equipped_items WHERE traveler_id=t.id),'{}'::jsonb));
  ELSIF p_operation = 'start' THEN
    IF p_payload->'player'->>'id' IS DISTINCT FROM t.id::text
       OR (p_payload->'opponent'->>'id' NOT IN ('training-apprentice','training-balanced','training-guardian','training-tactician') AND NOT EXISTS(SELECT 1 FROM public.travelers WHERE user_id=p_user_id AND id::text=p_payload->'opponent'->>'id'))
       OR p_payload->'opponent'->>'id' IS NULL THEN
      RAISE EXCEPTION 'Invalid battle' USING ERRCODE='22023';
    END IF;
    IF (SELECT count(*) FROM economy_private.battles WHERE traveler_id=t.id AND created_at > now()-interval '1 minute') >= 10 THEN
      RAISE EXCEPTION 'Too many battles' USING ERRCODE='54000';
    END IF;
    INSERT INTO economy_private.battles(traveler_id,seed,player,opponent)
      VALUES(t.id, floor(random()*4294967296)::bigint,p_payload->'player',p_payload->'opponent') RETURNING * INTO b;
  ELSIF p_operation IN ('battle','settle') THEN
    SELECT * INTO b FROM economy_private.battles WHERE id=(p_payload->>'battleId')::uuid AND traveler_id=t.id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF;
    IF p_operation = 'settle' THEN
      IF b.settled_at IS NOT NULL THEN RETURN b.reward; END IF;
      -- won is supplied ONLY by the server replay; authenticated cannot call this function.
      IF jsonb_typeof(p_payload->'won') IS DISTINCT FROM 'boolean' THEN
        RAISE EXCEPTION 'Invalid result' USING ERRCODE='22023';
      END IF;
      won := (p_payload->>'won')::boolean;
      IF b.created_at < now()-interval '24 hours' THEN
        RAISE EXCEPTION 'Battle expired' USING ERRCODE='22023';
      END IF;
      SELECT count(*) INTO quota FROM economy_private.battles
        WHERE traveler_id=t.id AND opponent->>'id'=b.opponent->>'id'
          AND settled_at >= date_trunc('day',now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'
          AND reward->>'rewarded'='true';
      result_value := jsonb_build_object('xp',CASE WHEN won AND quota<3 THEN 8 ELSE 0 END,
        'coins',CASE WHEN won AND quota<3 THEN 3 ELSE 0 END,'rewarded',won AND quota<3,
        'reason',CASE WHEN NOT won THEN 'defeat' WHEN quota>=3 THEN 'daily-limit' ELSE 'victory' END);
      IF won AND quota<3 THEN
        prior_xp := t.xp; next_xp := prior_xp+8;
        new_level := least(50,greatest(1,floor((1+sqrt(1+next_xp::numeric/25))/2)::integer));
        UPDATE public.travelers SET xp=next_xp,level=new_level WHERE id=t.id;
        UPDATE public.wallets SET coins=coins+3+CASE WHEN prior_xp<200 AND next_xp>=200 THEN 10 ELSE 0 END WHERE traveler_id=t.id;
        IF NOT FOUND THEN RAISE EXCEPTION 'Wallet missing'; END IF;
      END IF;
      UPDATE economy_private.battles SET settled_at=now(),reward=result_value WHERE id=b.id;
      RETURN result_value;
    END IF;
  ELSIF p_operation = 'purchase' THEN
    price_value := CASE p_payload->>'itemId' WHEN 'traveler-sword-common' THEN 35 WHEN 'traveler-armor-uncommon' THEN 65 WHEN 'traveler-shield-rare' THEN 115 ELSE NULL END;
    IF price_value IS NULL THEN RAISE EXCEPTION 'Invalid offer' USING ERRCODE='22023'; END IF;
    IF EXISTS(SELECT 1 FROM public.inventory WHERE traveler_id=t.id AND item_id=p_payload->>'itemId') THEN
      RETURN jsonb_build_object('status','owned');
    END IF;
    UPDATE public.wallets SET coins=coins-price_value WHERE traveler_id=t.id AND coins>=price_value RETURNING coins INTO balance;
    IF NOT FOUND THEN RAISE EXCEPTION 'Insufficient balance' USING ERRCODE='P0001'; END IF;
    INSERT INTO public.inventory(traveler_id,item_id,quantity,metadata)
      VALUES(t.id,p_payload->>'itemId',1,jsonb_build_object('source','shop','pricePaid',price_value));
    RETURN jsonb_build_object('status','purchased','coins',balance,'pricePaid',price_value);
  ELSE
    RAISE EXCEPTION 'Invalid operation' USING ERRCODE='22023';
  END IF;
  RETURN jsonb_build_object('id',b.id,'travelerId',b.traveler_id,'seed',b.seed,'player',b.player,'opponent',b.opponent);
END $function$

CREATE OR REPLACE FUNCTION economy_private.chest(p_traveler_id uuid, p_chest_type text, p_operation_id uuid, p_open boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE previous_type text;
BEGIN
 IF auth.uid() IS NULL OR NOT public.owns_traveler(p_traveler_id) OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=auth.uid() AND NOT coalesce(is_anonymous,false)) THEN RAISE EXCEPTION 'Account denied' USING ERRCODE='42501'; END IF;
 IF p_operation_id IS NULL OR p_chest_type IS NULL OR p_open IS NULL THEN RAISE EXCEPTION 'Invalid operation' USING ERRCODE='22023'; END IF;
 PERFORM 1 FROM public.travelers WHERE id=p_traveler_id AND economic_verified_at IS NOT NULL FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Legacy reconciliation required' USING ERRCODE='42501'; END IF;
 SELECT chest_type INTO previous_type FROM public.chest_operations WHERE traveler_id=p_traveler_id AND operation_key=(CASE WHEN p_open THEN 'open:' ELSE 'purchase:' END)||p_operation_id;
 IF FOUND AND previous_type IS DISTINCT FROM p_chest_type THEN RAISE EXCEPTION 'Operation conflict' USING ERRCODE='22023'; END IF;
 IF p_open THEN RETURN economy_private.open_chest(p_traveler_id,p_chest_type,p_operation_id); END IF;
 RETURN economy_private.purchase_chest(p_traveler_id,p_chest_type,p_operation_id);
END $function$

CREATE OR REPLACE FUNCTION economy_private.claim_phase_chest(p_traveler_id uuid, p_reward_key text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF auth.uid() IS NULL OR NOT public.owns_traveler(p_traveler_id) THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.travelers WHERE id=p_traveler_id FOR UPDATE;
 IF p_reward_key IS DISTINCT FROM 'phase:garden-choice' OR NOT EXISTS(SELECT 1 FROM economy_private.journey_rewards WHERE traveler_id=p_traveler_id AND reward_key=p_reward_key) THEN RAISE EXCEPTION 'Phase not verified' USING ERRCODE='42501'; END IF;
 RETURN public.grant_traveler_chest(p_traveler_id,'common','phase_completion',p_reward_key);
END $function$

CREATE OR REPLACE FUNCTION economy_private.create_traveler(p_id uuid, p_name text, p_body_type text, p_skin_tone text, p_hair_style text, p_hair_color text, p_avatar_variant text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE current_user_id uuid:=auth.uid();
BEGIN
 IF current_user_id IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF;
 UPDATE public.travelers SET is_active=false WHERE user_id=current_user_id AND is_active=true;
 INSERT INTO public.travelers(id,user_id,name,body_type,skin_tone,hair_style,hair_color,avatar_variant,level,xp,is_active)
 VALUES(p_id,current_user_id,p_name,p_body_type,p_skin_tone,p_hair_style,p_hair_color,p_avatar_variant,1,0,true);
 INSERT INTO public.traveler_stats(traveler_id) VALUES(p_id);
 INSERT INTO public.wallets(traveler_id) VALUES(p_id);
 RETURN p_id;
END $function$

CREATE OR REPLACE FUNCTION economy_private.get_owned_cards(p_traveler_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor uuid := auth.uid();
BEGIN
 IF actor IS NULL OR NOT EXISTS(SELECT 1 FROM auth.users
   WHERE id=actor AND NOT coalesce(is_anonymous,false)) THEN
  RAISE EXCEPTION 'Account denied' USING ERRCODE='42501';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.travelers
   WHERE id=p_traveler_id AND user_id=actor) THEN
  RAISE EXCEPTION 'Ownership denied' USING ERRCODE='42501';
 END IF;
 RETURN economy_private.collection(actor,p_traveler_id);
END $function$

CREATE OR REPLACE FUNCTION economy_private.open_chest(p_traveler_id uuid, p_chest_type text, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  operation_key_value text := 'open:' || p_operation_id::text;
  chest_row public.traveler_chests%ROWTYPE;
  reward_coins integer;
  reward_item_id text;
  reward_item_name text;
  roll_value double precision;
  origin_value text;
  remaining integer;
  result_value jsonb;
BEGIN
  IF NOT public.owns_traveler(p_traveler_id) THEN RAISE EXCEPTION 'Traveler not owned' USING ERRCODE = '42501'; END IF;
  SELECT rewards INTO result_value FROM public.chest_operations WHERE traveler_id = p_traveler_id AND operation_key = operation_key_value;
  IF FOUND THEN RETURN result_value || jsonb_build_object('duplicate', true); END IF;
  SELECT * INTO chest_row FROM public.traveler_chests WHERE traveler_id = p_traveler_id AND chest_type = p_chest_type AND quantity > 0 FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Chest unavailable' USING ERRCODE = 'P0002'; END IF;
  origin_value := coalesce(chest_row.sources->>0, 'unknown');
  roll_value := random();
  IF p_chest_type = 'common' THEN
    IF roll_value < .80 THEN reward_coins := 25; ELSE reward_coins := 10; reward_item_id := 'traveler-sword-common'; reward_item_name := 'Espada do Caminho'; END IF;
  ELSIF p_chest_type = 'uncommon' THEN
    IF roll_value < .70 THEN reward_coins := 55; ELSE reward_coins := 20; reward_item_id := 'traveler-armor-uncommon'; reward_item_name := 'Couraça do Viajante'; END IF;
  ELSIF p_chest_type = 'rare' THEN
    IF roll_value < .65 THEN reward_coins := 105; ELSE reward_coins := 35; reward_item_id := 'traveler-shield-rare'; reward_item_name := 'Escudo da Perseverança'; END IF;
  ELSIF p_chest_type = 'epic' THEN
    IF roll_value < .55 THEN reward_coins := 190; ELSE reward_coins := 70; reward_item_id := 'traveler-helmet-rare'; reward_item_name := 'Elmo do Viajante'; END IF;
  ELSIF p_chest_type = 'extraordinary' THEN
    IF roll_value < .50 THEN reward_coins := 360; ELSE reward_coins := 120; reward_item_id := 'wisdom-amulet'; reward_item_name := 'Medalhão do Caminho'; END IF;
  ELSE RAISE EXCEPTION 'Invalid chest type' USING ERRCODE = '22023';
  END IF;
  remaining := chest_row.quantity - 1;
  IF remaining = 0 THEN
    DELETE FROM public.traveler_chests WHERE traveler_id = p_traveler_id AND chest_type = p_chest_type;
  ELSE
    UPDATE public.traveler_chests SET quantity = remaining, sources = sources - 0 WHERE traveler_id = p_traveler_id AND chest_type = p_chest_type;
  END IF;
  PERFORM public.add_coins(p_traveler_id, reward_coins);
  IF reward_item_id IS NOT NULL THEN
    INSERT INTO public.inventory(traveler_id, item_id, quantity, metadata)
    VALUES (p_traveler_id, reward_item_id, 1, jsonb_build_object('source', 'chest', 'chestType', p_chest_type))
    ON CONFLICT (traveler_id, item_id) DO UPDATE SET quantity = public.inventory.quantity + 1;
  END IF;
  result_value := jsonb_build_object('chestType', p_chest_type, 'coins', reward_coins, 'itemId', reward_item_id, 'itemName', reward_item_name, 'source', origin_value, 'remainingQuantity', remaining, 'duplicate', false);
  INSERT INTO public.chest_operations(traveler_id, operation_key, operation_type, chest_type, source, rewards)
  VALUES (p_traveler_id, operation_key_value, 'open', p_chest_type, origin_value, result_value);
  RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION economy_private.protect_journey_checkpoint()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE p jsonb;
BEGIN
 SELECT state->'progress' INTO p FROM economy_private.journeys WHERE traveler_id=NEW.id;
 IF p IS NOT NULL THEN NEW.journey_progress:=coalesce(NEW.journey_progress,'{}'::jsonb)||p; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION economy_private.purchase_chest(p_traveler_id uuid, p_chest_type text, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  operation_key_value text := 'purchase:' || p_operation_id::text;
  price_value integer;
  required_level integer;
  resulting_coins integer;
  prior_result jsonb;
BEGIN
  IF NOT public.owns_traveler(p_traveler_id) THEN RAISE EXCEPTION 'Traveler not owned' USING ERRCODE = '42501'; END IF;
  SELECT rewards INTO prior_result FROM public.chest_operations WHERE traveler_id = p_traveler_id AND operation_key = operation_key_value;
  IF FOUND THEN RETURN prior_result || jsonb_build_object('duplicate', true); END IF;
  price_value := CASE p_chest_type WHEN 'common' THEN 40 WHEN 'uncommon' THEN 90 WHEN 'rare' THEN 180 ELSE NULL END;
  required_level := CASE p_chest_type WHEN 'common' THEN 1 WHEN 'uncommon' THEN 1 WHEN 'rare' THEN 3 ELSE NULL END;
  IF price_value IS NULL THEN RAISE EXCEPTION 'Chest unavailable for purchase' USING ERRCODE = '22023'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.travelers WHERE id = p_traveler_id AND level >= required_level) THEN RAISE EXCEPTION 'Traveler level too low' USING ERRCODE = 'P0001'; END IF;
  INSERT INTO public.chest_operations(traveler_id, operation_key, operation_type, chest_type, source, price_paid, rewards)
  VALUES (p_traveler_id, operation_key_value, 'purchase', p_chest_type, 'shop', price_value, '{}'::jsonb)
  ON CONFLICT (traveler_id, operation_key) DO NOTHING;
  IF NOT FOUND THEN
    SELECT rewards INTO prior_result FROM public.chest_operations WHERE traveler_id = p_traveler_id AND operation_key = operation_key_value;
    RETURN prior_result || jsonb_build_object('duplicate', true);
  END IF;
  resulting_coins := public.spend_coins(p_traveler_id, price_value);
  INSERT INTO public.traveler_chests(traveler_id, chest_type, quantity, sources)
  VALUES (p_traveler_id, p_chest_type, 1, jsonb_build_array('shop'))
  ON CONFLICT (traveler_id, chest_type) DO UPDATE
  SET quantity = public.traveler_chests.quantity + 1,
      sources = public.traveler_chests.sources || jsonb_build_array('shop'),
      updated_at = now();
  prior_result := jsonb_build_object('chestType', p_chest_type, 'quantityAdded', 1, 'coins', resulting_coins, 'pricePaid', price_value, 'duplicate', false);
  UPDATE public.chest_operations SET rewards = prior_result WHERE traveler_id = p_traveler_id AND operation_key = operation_key_value;
  RETURN prior_result;
END $function$

CREATE OR REPLACE FUNCTION public.grant_traveler_chest(p_traveler_id uuid, p_chest_type text, p_source text, p_operation_key text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF p_chest_type NOT IN ('common','uncommon','rare','epic','extraordinary') OR char_length(p_source) NOT BETWEEN 1 AND 120 OR char_length(p_operation_key) NOT BETWEEN 1 AND 160 THEN
    RAISE EXCEPTION 'Invalid chest grant' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.travelers WHERE id = p_traveler_id) THEN
    RAISE EXCEPTION 'Traveler not found' USING ERRCODE = 'P0002';
  END IF;
  INSERT INTO public.chest_operations(traveler_id, operation_key, operation_type, chest_type, source)
  VALUES (p_traveler_id, p_operation_key, 'grant', p_chest_type, p_source)
  ON CONFLICT (traveler_id, operation_key) DO NOTHING;
  IF NOT FOUND THEN RETURN false; END IF;
  INSERT INTO public.traveler_chests(traveler_id, chest_type, quantity, sources)
  VALUES (p_traveler_id, p_chest_type, 1, jsonb_build_array(p_source))
  ON CONFLICT (traveler_id, chest_type) DO UPDATE
  SET quantity = public.traveler_chests.quantity + 1,
      sources = public.traveler_chests.sources || jsonb_build_array(p_source),
      updated_at = now();
  RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.guild_activity_capture()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE event_name text; guild_key uuid; actor_key uuid; entity_kind text; entity_key uuid;
BEGIN
  IF TG_TABLE_NAME = 'guilds' THEN
    IF TG_OP <> 'INSERT' THEN RETURN NEW; END IF;
    event_name := 'guild_created'; guild_key := NEW.id; actor_key := NEW.leader_traveler_id; entity_kind := 'guild'; entity_key := NEW.id;
  ELSIF TG_TABLE_NAME = 'guild_members' THEN
    IF TG_OP = 'INSERT' AND NEW.role <> 'leader' AND NEW.status = 'active' THEN event_name := 'member_joined';
    ELSIF TG_OP = 'UPDATE' AND NEW.status IS DISTINCT FROM OLD.status THEN
      event_name := CASE NEW.status WHEN 'active' THEN 'member_joined' WHEN 'left' THEN 'member_left' WHEN 'removed' THEN 'member_removed' ELSE NULL END;
    END IF;
    guild_key := NEW.guild_id; actor_key := NEW.traveler_id; entity_kind := 'member'; entity_key := NEW.traveler_id;
    IF event_name = 'member_removed' THEN
      SELECT gm.traveler_id INTO actor_key FROM public.guild_members gm JOIN public.travelers t ON t.id = gm.traveler_id
      WHERE gm.guild_id = NEW.guild_id AND gm.role = 'leader' AND gm.status = 'active' AND t.user_id = auth.uid() LIMIT 1;
    END IF;
  ELSIF TG_TABLE_NAME = 'guild_missions' THEN
    IF TG_OP = 'INSERT' THEN event_name := 'mission_created';
    ELSIF NEW.status IS DISTINCT FROM OLD.status THEN
      event_name := CASE NEW.status WHEN 'published' THEN 'mission_published' WHEN 'closed' THEN 'mission_closed' WHEN 'cancelled' THEN 'draft_deleted' ELSE NULL END;
    END IF;
    guild_key := NEW.guild_id; actor_key := NEW.created_by_traveler_id; entity_kind := 'mission'; entity_key := NEW.id;
  ELSIF TG_TABLE_NAME = 'guild_mission_progress' THEN
    IF TG_OP = 'UPDATE' AND NEW.status IS DISTINCT FROM OLD.status THEN
      event_name := CASE NEW.status WHEN 'pending_approval' THEN 'mission_submitted' WHEN 'completed' THEN 'mission_completed' WHEN 'rejected' THEN 'mission_rejected' ELSE NULL END;
    END IF;
    SELECT guild_id INTO guild_key FROM public.guild_missions WHERE id = NEW.mission_id;
    actor_key := coalesce(NEW.approved_by_traveler_id, NEW.traveler_id); entity_kind := 'mission'; entity_key := NEW.mission_id;
  ELSIF TG_TABLE_NAME = 'guild_reward_claims' THEN
    IF TG_OP = 'INSERT' THEN event_name := 'reward_processed'; END IF;
    SELECT guild_id INTO guild_key FROM public.guild_missions WHERE id = NEW.mission_id;
    actor_key := NEW.traveler_id; entity_kind := 'mission'; entity_key := NEW.mission_id;
  END IF;
  IF event_name IS NOT NULL THEN
    INSERT INTO public.guild_activity_log(guild_id, actor_traveler_id, event_type, entity_type, entity_id)
    VALUES (guild_key, actor_key, event_name, entity_kind, entity_key);
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION guild_chat_private.moderate(p_guild_id uuid, p_traveler_id uuid, p_message_id uuid, p_action text, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor_role text; message public.guild_chat_messages%ROWTYPE;
BEGIN
  actor_role:=guild_chat_private.actor(p_guild_id,p_traveler_id);
  IF actor_role NOT IN ('leader','co_leader','moderator') THEN RAISE EXCEPTION 'Moderator required' USING ERRCODE='42501'; END IF;
  IF p_action IS NULL OR p_action NOT IN ('remove','dismiss_reports') OR p_reason IS NULL OR char_length(btrim(p_reason)) NOT BETWEEN 3 AND 200 THEN RAISE EXCEPTION 'Invalid moderation' USING ERRCODE='22023'; END IF;
  SELECT * INTO message FROM public.guild_chat_messages WHERE id=p_message_id AND guild_id=p_guild_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Message unavailable' USING ERRCODE='42501'; END IF;
  IF p_action='remove' THEN
    IF message.removed_at IS NOT NULL THEN RETURN; END IF;
    UPDATE public.guild_chat_messages SET body=NULL,removed_at=clock_timestamp() WHERE id=p_message_id;
    UPDATE public.guild_chat_reports SET status='removed' WHERE message_id=p_message_id AND status='pending';
  ELSE
    UPDATE public.guild_chat_reports SET status='dismissed' WHERE message_id=p_message_id AND status='pending';
    IF NOT FOUND THEN RETURN; END IF;
  END IF;
  INSERT INTO public.guild_chat_moderation_log(guild_id,message_id,actor_traveler_id,action,reason) VALUES(p_guild_id,p_message_id,p_traveler_id,p_action,btrim(p_reason));
END $function$

CREATE OR REPLACE FUNCTION guild_chat_private.report(p_guild_id uuid, p_traveler_id uuid, p_message_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  PERFORM guild_chat_private.actor(p_guild_id,p_traveler_id);
  IF p_reason IS NULL OR p_reason NOT IN ('bullying','personal_data','sexual_content','violence','other') THEN RAISE EXCEPTION 'Invalid report reason' USING ERRCODE='22023'; END IF;
  PERFORM 1 FROM public.guild_chat_messages WHERE id=p_message_id AND guild_id=p_guild_id AND removed_at IS NULL FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Message unavailable' USING ERRCODE='42501'; END IF;
  IF EXISTS(SELECT 1 FROM public.guild_chat_reports WHERE message_id=p_message_id AND reporter_traveler_id=p_traveler_id) THEN RETURN; END IF;
  PERFORM guild_chat_private.take_rate('report');
  INSERT INTO public.guild_chat_reports(guild_id,message_id,reporter_traveler_id,reason) VALUES(p_guild_id,p_message_id,p_traveler_id,p_reason) ON CONFLICT DO NOTHING;
END $function$

CREATE OR REPLACE FUNCTION guild_chat_private.send(p_guild_id uuid, p_traveler_id uuid, p_client_id uuid, p_body text, p_announcement boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor_role text; author public.travelers%ROWTYPE; previous public.guild_chat_messages%ROWTYPE; result_id uuid;
BEGIN
  actor_role:=guild_chat_private.actor(p_guild_id,p_traveler_id);
  IF p_body IS NULL OR char_length(btrim(p_body)) NOT BETWEEN 1 AND 1000 OR octet_length(p_body)>4000 OR p_client_id IS NULL OR p_announcement IS NULL THEN RAISE EXCEPTION 'Invalid chat message' USING ERRCODE='22023'; END IF;
  IF p_announcement AND actor_role<>'leader' THEN RAISE EXCEPTION 'Leader required' USING ERRCODE='42501'; END IF;
  -- Serialize guild insert commits so read cursors cannot skip a late commit.
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_guild_id::text,63));
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(auth.uid()::text,62));
  SELECT * INTO previous FROM public.guild_chat_messages WHERE author_traveler_id=p_traveler_id AND client_id=p_client_id;
  IF FOUND THEN
    IF previous.guild_id<>p_guild_id OR previous.body IS DISTINCT FROM btrim(p_body) OR previous.is_announcement<>p_announcement THEN RAISE EXCEPTION 'Chat retry conflict' USING ERRCODE='22023'; END IF;
    RETURN previous.id;
  END IF;
  PERFORM guild_chat_private.take_rate('send');
  SELECT * INTO author FROM public.travelers WHERE id=p_traveler_id;
  INSERT INTO public.guild_chat_messages(guild_id,author_traveler_id,client_id,author_name,author_body_type,author_skin_tone,author_hair_style,author_outfit,body,is_announcement)
    VALUES(p_guild_id,p_traveler_id,p_client_id,author.name,author.body_type,author.skin_tone,author.hair_style,coalesce(author.avatar_variant,'musgo'),btrim(p_body),p_announcement) RETURNING id INTO result_id;
  RETURN result_id;
END $function$

CREATE OR REPLACE FUNCTION guild_chat_private.summary(p_guild_id uuid, p_traveler_id uuid)
 RETURNS TABLE(unread_count bigint, last_read_sequence bigint, can_announce boolean, can_moderate boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor_role text; checkpoint bigint;
BEGIN
  actor_role:=guild_chat_private.actor(p_guild_id,p_traveler_id);
  SELECT r.last_read_sequence INTO checkpoint FROM public.guild_chat_reads r WHERE r.guild_id=p_guild_id AND r.user_id=auth.uid();
  checkpoint:=coalesce(checkpoint,0);
  RETURN QUERY SELECT count(*),checkpoint,actor_role='leader',actor_role IN ('leader','co_leader','moderator') FROM public.guild_chat_messages m
    WHERE m.guild_id=p_guild_id AND m.sequence>checkpoint AND m.removed_at IS NULL
      AND NOT EXISTS(SELECT 1 FROM public.travelers t WHERE t.id=m.author_traveler_id AND t.user_id=auth.uid());
END $function$

CREATE OR REPLACE FUNCTION guild_chat_private.take_rate(p_kind text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE bucket guild_chat_private.rate_limits%ROWTYPE; stamp timestamptz; cap integer;
BEGIN
  IF auth.uid() IS NULL OR p_kind NOT IN ('send','report') THEN RAISE EXCEPTION 'Chat access denied' USING ERRCODE='42501'; END IF;
  cap:=CASE WHEN p_kind='send' THEN 10 ELSE 5 END;
  INSERT INTO guild_chat_private.rate_limits(user_id,kind) VALUES(auth.uid(),p_kind) ON CONFLICT DO NOTHING;
  SELECT * INTO bucket FROM guild_chat_private.rate_limits WHERE user_id=auth.uid() AND kind=p_kind FOR UPDATE;
  stamp:=clock_timestamp();
  IF bucket.last_at > stamp-interval '3 seconds' THEN RAISE EXCEPTION 'Chat rate limit' USING ERRCODE='P0001'; END IF;
  IF bucket.window_at <= stamp-interval '1 minute' THEN bucket.hits:=0; bucket.window_at:=stamp; END IF;
  IF bucket.hits>=cap THEN RAISE EXCEPTION 'Chat rate limit' USING ERRCODE='P0001'; END IF;
  UPDATE guild_chat_private.rate_limits SET last_at=stamp,window_at=bucket.window_at,hits=bucket.hits+1 WHERE user_id=auth.uid() AND kind=p_kind;
END $function$

CREATE OR REPLACE FUNCTION guild_invite_private.create_invite(p_leader uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE guild_key uuid; raw_token text; new_row guild_invite_private.link_invites;
  issued_at timestamptz := clock_timestamp();
BEGIN
  guild_key := guild_invite_private.leader_guild(p_leader);
  IF (SELECT count(*) FROM guild_invite_private.link_invites
      WHERE guild_id = guild_key AND revoked_at IS NULL AND expires_at > clock_timestamp()) >= 10 THEN
    RAISE EXCEPTION 'Active invite limit reached' USING ERRCODE = '54000';
  END IF;
  raw_token := encode(extensions.gen_random_bytes(32), 'hex');
  INSERT INTO guild_invite_private.link_invites(guild_id, leader_traveler_id, token_hash, created_at, expires_at)
    VALUES (guild_key, p_leader, extensions.digest(raw_token, 'sha256'), issued_at, issued_at + interval '7 days')
    RETURNING * INTO new_row;
  RETURN jsonb_build_object('id', new_row.id, 'token', raw_token, 'expires_at', new_row.expires_at);
END $function$

CREATE OR REPLACE FUNCTION guild_invite_private.preview_invite(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE invite_row guild_invite_private.link_invites; guild_name text;
BEGIN
  invite_row := guild_invite_private.valid_invite(p_token);
  SELECT name INTO guild_name FROM public.guilds WHERE id = invite_row.guild_id;
  RETURN jsonb_build_object('guild_name', guild_name, 'expires_at', invite_row.expires_at);
END $function$

CREATE OR REPLACE FUNCTION guild_invite_private.request_invite(p_token text, p_traveler uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE invite_row guild_invite_private.link_invites;
BEGIN
  PERFORM guild_invite_private.require_account();
  invite_row := guild_invite_private.valid_invite(p_token);
  IF NOT public.owns_traveler(p_traveler) THEN
    RAISE EXCEPTION 'Traveler not owned' USING ERRCODE = '42501';
  END IF;
  -- Existing RPC creates/reuses a PENDING request; only its normal review may add membership.
  RETURN public.request_join_guild(invite_row.guild_id, p_traveler);
END $function$

CREATE OR REPLACE FUNCTION guild_invite_private.resolve_invite(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE invite_row guild_invite_private.link_invites; guild_name text;
BEGIN
  PERFORM guild_invite_private.require_account();
  invite_row := guild_invite_private.valid_invite(p_token);
  SELECT name INTO guild_name FROM public.guilds WHERE id = invite_row.guild_id;
  RETURN jsonb_build_object('guild_name', guild_name, 'expires_at', invite_row.expires_at);
END $function$

CREATE OR REPLACE FUNCTION guild_invite_private.revoke_invite(p_id uuid, p_leader uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE guild_key uuid;
BEGIN
  guild_key := guild_invite_private.leader_guild(p_leader);
  UPDATE guild_invite_private.link_invites SET revoked_at = coalesce(revoked_at, clock_timestamp())
    WHERE id = p_id AND guild_id = guild_key;
  IF NOT FOUND THEN RAISE EXCEPTION 'Invite unavailable' USING ERRCODE = 'P0002'; END IF;
END $function$

CREATE OR REPLACE FUNCTION public.guild_mission_workspace(p_actor uuid, p_history_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_guild uuid; v_role text; v_result jsonb;
BEGIN
 SELECT guild_id INTO v_guild FROM public.guild_members WHERE traveler_id=p_actor AND status='active';
 v_role:=guild_ops.actor(p_actor,v_guild);
 IF p_history_offset IS NULL OR p_history_offset<0 OR p_history_offset>10000 THEN RAISE EXCEPTION 'Invalid history page'; END IF;
 SELECT jsonb_build_object('version',1,'guildId',v_guild,'missions',coalesce((SELECT jsonb_agg(to_jsonb(m) ORDER BY m.created_at DESC) FROM public.guild_missions m WHERE m.guild_id=v_guild AND guild_ops.visible(m.id) AND (v_role='leader' OR (m.status<>'draft' AND ((m.status='published' AND (m.audience='all' OR p_actor=ANY(m.target_traveler_ids))) OR EXISTS(SELECT 1 FROM public.guild_mission_progress own WHERE own.mission_id=m.id AND own.traveler_id=p_actor))))),'[]'::jsonb),
 'progress',coalesce((SELECT jsonb_agg(to_jsonb(p)) FROM public.guild_mission_progress p JOIN public.guild_missions m ON m.id=p.mission_id WHERE m.guild_id=v_guild AND (v_role='leader' OR p.traveler_id=p_actor) AND guild_ops.visible(m.id)),'[]'::jsonb),
 'attempts',coalesce((SELECT jsonb_agg(to_jsonb(a)||jsonb_build_object('traveler_name',t.name) ORDER BY a.submitted_at) FROM public.guild_mission_attempts a JOIN public.guild_missions m ON m.id=a.mission_id JOIN public.travelers t ON t.id=a.traveler_id WHERE m.guild_id=v_guild AND (v_role='leader' OR a.traveler_id=p_actor) AND guild_ops.visible(m.id)),'[]'::jsonb),
 'history',CASE WHEN v_role='leader' THEN coalesce((SELECT jsonb_agg(to_jsonb(h)) FROM (SELECT * FROM public.guild_activity_log WHERE guild_id=v_guild ORDER BY created_at DESC,id DESC LIMIT 20 OFFSET p_history_offset) h),'[]'::jsonb) ELSE '[]'::jsonb END) INTO v_result;
 RETURN v_result;
END $function$

CREATE OR REPLACE FUNCTION public.guild_public_member_profile(p_requester_traveler_id uuid, p_member_traveler_id uuid)
 RETURNS TABLE(level integer, completed_missions bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE guild_key uuid;
BEGIN
  IF NOT public.owns_traveler(p_requester_traveler_id) THEN
    RAISE EXCEPTION 'Member unavailable' USING ERRCODE = '42501';
  END IF;
  SELECT guild_id INTO guild_key FROM public.guild_members
    WHERE traveler_id = p_requester_traveler_id AND status = 'active';
  IF guild_key IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.guild_members WHERE guild_id = guild_key
      AND traveler_id = p_member_traveler_id AND status = 'active'
  ) THEN RAISE EXCEPTION 'Member unavailable' USING ERRCODE = '42501'; END IF;
  RETURN QUERY SELECT t.level,
    (SELECT count(*) FROM public.guild_mission_progress p JOIN public.guild_missions m ON m.id = p.mission_id
      WHERE m.guild_id = guild_key AND p.traveler_id = p_member_traveler_id AND p.status = 'completed')
    FROM public.travelers t WHERE t.id = p_member_traveler_id;
END $function$

CREATE OR REPLACE FUNCTION public.request_join_guild(p_guild_id uuid, p_traveler_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE request_id uuid;
BEGIN
  IF NOT public.owns_traveler(p_traveler_id) THEN RAISE EXCEPTION 'Traveler not owned' USING ERRCODE = '42501'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.guilds WHERE id = p_guild_id AND status = 'active') THEN RAISE EXCEPTION 'Guild unavailable' USING ERRCODE = 'P0002'; END IF;
  IF EXISTS (SELECT 1 FROM public.guild_members WHERE traveler_id = p_traveler_id AND status = 'active') THEN RAISE EXCEPTION 'Traveler already belongs to a guild' USING ERRCODE = '23505'; END IF;
  INSERT INTO public.guild_join_requests(guild_id, traveler_id) VALUES (p_guild_id, p_traveler_id)
  ON CONFLICT (guild_id, traveler_id) WHERE status = 'pending' DO UPDATE SET updated_at = now()
  RETURNING id INTO request_id;
  RETURN request_id;
END $function$

CREATE OR REPLACE FUNCTION public.review_guild_join_request(p_request_id uuid, p_reviewer_traveler_id uuid, p_approve boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE request_row public.guild_join_requests%ROWTYPE;
BEGIN
  IF NOT public.owns_traveler(p_reviewer_traveler_id) THEN RAISE EXCEPTION 'Reviewer not owned' USING ERRCODE = '42501'; END IF;
  SELECT * INTO request_row FROM public.guild_join_requests WHERE id = p_request_id AND status = 'pending' FOR UPDATE;
  IF NOT FOUND OR NOT EXISTS (SELECT 1 FROM public.guild_members WHERE guild_id = request_row.guild_id AND traveler_id = p_reviewer_traveler_id AND role = 'leader' AND status = 'active') THEN RAISE EXCEPTION 'Request unavailable' USING ERRCODE = '42501'; END IF;
  IF p_approve AND EXISTS (SELECT 1 FROM public.guild_members WHERE traveler_id = request_row.traveler_id AND status = 'active') THEN RAISE EXCEPTION 'Traveler already belongs to a guild' USING ERRCODE = '23505'; END IF;
  UPDATE public.guild_join_requests SET status = CASE WHEN p_approve THEN 'accepted' ELSE 'rejected' END, reviewed_by_traveler_id = p_reviewer_traveler_id, reviewed_at = now() WHERE id = p_request_id;
  IF p_approve THEN
    INSERT INTO public.guild_members(guild_id, traveler_id, role, status) VALUES (request_row.guild_id, request_row.traveler_id, 'member', 'active')
    ON CONFLICT (guild_id, traveler_id) DO UPDATE SET role = 'member', status = 'active', joined_at = now(), updated_at = now();
  END IF;
END $function$

CREATE OR REPLACE FUNCTION public.review_guild_mission_v2(p_actor uuid, p_attempt uuid, p_revision integer, p_decision text, p_reason text, p_request uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a public.guild_mission_attempts; m public.guild_missions; p public.guild_mission_progress;
BEGIN
 SELECT * INTO a FROM public.guild_mission_attempts WHERE id=p_attempt;
 SELECT * INTO m FROM public.guild_missions WHERE id=a.mission_id FOR UPDATE;
 PERFORM guild_ops.actor(p_actor,m.guild_id,true);
 PERFORM 1 FROM public.guild_members gm WHERE gm.guild_id=m.guild_id AND gm.traveler_id=a.traveler_id AND gm.status='active' FOR SHARE;
 IF NOT FOUND OR EXISTS(SELECT 1 FROM public.travelers WHERE id=a.traveler_id AND user_id=auth.uid()) THEN RAISE EXCEPTION 'Self review or inactive member' USING ERRCODE='42501'; END IF;
 SELECT * INTO a FROM public.guild_mission_attempts WHERE id=p_attempt FOR UPDATE;
 IF p_request IS NULL OR p_revision IS NULL OR p_revision<1 OR p_decision NOT IN ('approved','rejected','changes_requested') OR p_decision IS NULL OR length(coalesce(p_reason,''))>500 OR (p_decision<>'approved' AND length(btrim(coalesce(p_reason,'')))=0) THEN RAISE EXCEPTION 'Decision needs a valid reason'; END IF;
 IF a.decision IS NOT NULL THEN
   IF a.decision_request_id=p_request AND a.decision=p_decision AND coalesce(a.reason,'')=btrim(coalesce(p_reason,'')) THEN RETURN a.decision; END IF;
   RAISE EXCEPTION 'Submission already reviewed';
 END IF;
 SELECT * INTO p FROM public.guild_mission_progress WHERE mission_id=a.mission_id AND traveler_id=a.traveler_id FOR UPDATE;
 IF m.status='cancelled' OR a.revision<>p_revision OR p.submission_revision<>a.revision OR p.status<>'pending_approval' THEN RAISE EXCEPTION 'Stale submission'; END IF;
 IF p_decision='approved' AND length(btrim(a.note))=0 THEN RAISE EXCEPTION 'Evidence missing; request correction'; END IF;
 UPDATE public.guild_mission_attempts SET decision=p_decision,reason=nullif(btrim(coalesce(p_reason,'')),''),reviewer_traveler_id=p_actor,decided_at=clock_timestamp(),decision_request_id=p_request WHERE id=p_attempt;
 UPDATE public.guild_mission_progress SET status=p_decision,review_note=nullif(btrim(coalesce(p_reason,'')),''),approved_by_traveler_id=p_actor,approved_at=CASE WHEN p_decision='approved' THEN clock_timestamp() ELSE NULL END WHERE id=p.id;
 INSERT INTO public.guild_activity_log(guild_id,actor_traveler_id,event_type,entity_type,entity_id,metadata) VALUES(m.guild_id,p_actor,'mission_decision','mission',m.id,jsonb_build_object('decision',p_decision,'revision',a.revision));
 RETURN p_decision;
END $function$

CREATE OR REPLACE FUNCTION public.review_guild_mission_with_guidance(p_mission_id uuid, p_member_traveler_id uuid, p_reviewer_traveler_id uuid, p_approve boolean, p_guidance text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE next_status text;
BEGIN
  IF char_length(coalesce(p_guidance,'')) > 500 THEN RAISE EXCEPTION 'Guidance too long' USING ERRCODE = '22023'; END IF;
  next_status := public.review_guild_mission(p_mission_id, p_member_traveler_id, p_reviewer_traveler_id, p_approve);
  UPDATE public.guild_mission_progress SET review_note = CASE WHEN p_approve THEN NULL ELSE nullif(btrim(coalesce(p_guidance,'')),'') END
  WHERE mission_id = p_mission_id AND traveler_id = p_member_traveler_id;
  RETURN next_status;
END $function$

CREATE OR REPLACE FUNCTION public.review_guild_mission(p_mission_id uuid, p_member_traveler_id uuid, p_reviewer_traveler_id uuid, p_approve boolean)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE mission_guild_id uuid; next_status text;
BEGIN
  IF NOT public.owns_traveler(p_reviewer_traveler_id) THEN RAISE EXCEPTION 'Reviewer not owned' USING ERRCODE = '42501'; END IF;
  SELECT guild_id INTO mission_guild_id FROM public.guild_missions WHERE id = p_mission_id AND completion_mode = 'leader_approval';
  IF mission_guild_id IS NULL OR NOT EXISTS (SELECT 1 FROM public.guild_members WHERE guild_id = mission_guild_id AND traveler_id = p_reviewer_traveler_id AND role = 'leader' AND status = 'active') THEN RAISE EXCEPTION 'Leader role required' USING ERRCODE = '42501'; END IF;
  next_status := CASE WHEN p_approve THEN 'completed' ELSE 'rejected' END;
  UPDATE public.guild_mission_progress SET status = next_status, approved_at = CASE WHEN p_approve THEN now() ELSE NULL END, approved_by_traveler_id = p_reviewer_traveler_id, completed_at = CASE WHEN p_approve THEN now() ELSE NULL END WHERE mission_id = p_mission_id AND traveler_id = p_member_traveler_id AND status = 'pending_approval';
  IF NOT FOUND THEN RAISE EXCEPTION 'Pending submission unavailable' USING ERRCODE = 'P0001'; END IF;
  IF p_approve THEN
    PERFORM public.apply_guild_mission_reward(p_mission_id, p_member_traveler_id);
    UPDATE public.guild_mission_progress SET reward_claimed_at = now() WHERE mission_id = p_mission_id AND traveler_id = p_member_traveler_id;
  END IF;
  RETURN next_status;
END $function$

CREATE OR REPLACE FUNCTION public.save_guild_lesson(p_lesson_id uuid, p_leader_traveler_id uuid, p_title text, p_theme text, p_bible_reference text, p_bible_url text, p_introduction text, p_content text, p_main_points jsonb, p_discussion_questions jsonb, p_activity_text text, p_scheduled_at timestamp with time zone, p_related_mission_id uuid, p_publish boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE guild_key uuid; lesson_key uuid; current_status text; point text;
BEGIN
  IF NOT public.owns_traveler(p_leader_traveler_id) THEN RAISE EXCEPTION 'Leader unavailable' USING ERRCODE = '42501'; END IF;
  SELECT guild_id INTO guild_key FROM public.guild_members
    WHERE traveler_id = p_leader_traveler_id AND role = 'leader' AND status = 'active';
  IF guild_key IS NULL THEN RAISE EXCEPTION 'Leader unavailable' USING ERRCODE = '42501'; END IF;
  IF p_related_mission_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.guild_missions WHERE id = p_related_mission_id AND guild_id = guild_key AND status <> 'cancelled'
  ) THEN RAISE EXCEPTION 'Mission unavailable' USING ERRCODE = '42501'; END IF;
  IF jsonb_typeof(p_main_points) IS DISTINCT FROM 'array' OR jsonb_typeof(p_discussion_questions) IS DISTINCT FROM 'array'
  THEN RAISE EXCEPTION 'Invalid lesson list' USING ERRCODE = '22023'; END IF;
  IF jsonb_array_length(p_main_points) > 12 OR jsonb_array_length(p_discussion_questions) > 12
    OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_main_points) AS entry(value) WHERE jsonb_typeof(value) <> 'string')
    OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_discussion_questions) AS entry(value) WHERE jsonb_typeof(value) <> 'string')
  THEN RAISE EXCEPTION 'Invalid lesson list' USING ERRCODE = '22023'; END IF;
  FOR point IN SELECT value FROM jsonb_array_elements_text(p_main_points) AS entry(value)
    UNION ALL SELECT value FROM jsonb_array_elements_text(p_discussion_questions) AS entry(value)
  LOOP
    IF char_length(btrim(point)) < 2 OR char_length(point) > 300 THEN
      RAISE EXCEPTION 'Invalid lesson entry' USING ERRCODE = '22023';
    END IF;
  END LOOP;
  IF p_lesson_id IS NULL THEN
    INSERT INTO public.guild_lessons(guild_id, created_by_traveler_id, related_mission_id, title, theme,
      bible_reference, bible_url, introduction, content, main_points, discussion_questions, activity_text,
      scheduled_at, status, published_at)
    VALUES (guild_key, p_leader_traveler_id, p_related_mission_id, btrim(p_title), btrim(p_theme),
      btrim(p_bible_reference), nullif(btrim(coalesce(p_bible_url, '')), ''), coalesce(p_introduction, ''),
      coalesce(p_content, ''), p_main_points, p_discussion_questions, nullif(btrim(coalesce(p_activity_text, '')), ''),
      p_scheduled_at, CASE WHEN p_publish THEN 'published' ELSE 'draft' END, CASE WHEN p_publish THEN now() END)
    RETURNING id INTO lesson_key;
  ELSE
    SELECT status INTO current_status FROM public.guild_lessons
      WHERE id = p_lesson_id AND guild_id = guild_key FOR UPDATE;
    IF current_status IS DISTINCT FROM 'draft' THEN RAISE EXCEPTION 'Draft unavailable' USING ERRCODE = '42501'; END IF;
    UPDATE public.guild_lessons SET related_mission_id = p_related_mission_id, title = btrim(p_title), theme = btrim(p_theme),
      bible_reference = btrim(p_bible_reference), bible_url = nullif(btrim(coalesce(p_bible_url, '')), ''),
      introduction = coalesce(p_introduction, ''), content = coalesce(p_content, ''),
      main_points = p_main_points, discussion_questions = p_discussion_questions,
      activity_text = nullif(btrim(coalesce(p_activity_text, '')), ''), scheduled_at = p_scheduled_at,
      status = CASE WHEN p_publish THEN 'published' ELSE 'draft' END,
      published_at = CASE WHEN p_publish THEN now() ELSE NULL END
    WHERE id = p_lesson_id RETURNING id INTO lesson_key;
  END IF;
  RETURN lesson_key;
END $function$

CREATE OR REPLACE FUNCTION public.save_guild_mission_v2(p_actor uuid, p_mission uuid, p_expected_revision integer, p_data jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_guild uuid; v_old public.guild_missions; v_targets uuid[]; v_start timestamptz; v_due timestamptz; v_key text;
BEGIN
 IF p_actor IS NULL OR p_mission IS NULL OR p_expected_revision IS NULL OR p_expected_revision<0 THEN RAISE EXCEPTION 'Invalid mission request'; END IF;
 IF jsonb_typeof(p_data)<>'object' OR p_data IS NULL THEN RAISE EXCEPTION 'Invalid mission'; END IF;
 FOR v_key IN SELECT jsonb_object_keys(p_data) LOOP
   IF v_key NOT IN ('title','description','objective','instructions','evidenceCriterion','bibleReference','startsAt','dueAt','kind','rewardTier','audience','targetIds') THEN RAISE EXCEPTION 'Unexpected mission field'; END IF;
 END LOOP;
 FOREACH v_key IN ARRAY ARRAY['title','description','objective','instructions','evidenceCriterion','bibleReference','startsAt','dueAt','kind','rewardTier','audience'] LOOP
   IF jsonb_typeof(p_data->v_key) IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'Invalid mission field'; END IF;
 END LOOP;
 IF jsonb_typeof(p_data->'targetIds') IS DISTINCT FROM 'array' OR jsonb_array_length(p_data->'targetIds')>100 THEN RAISE EXCEPTION 'Invalid audience'; END IF;
 SELECT coalesce(array_agg(value::uuid),'{}'::uuid[]) INTO v_targets FROM jsonb_array_elements_text(p_data->'targetIds');
 v_start:=nullif(p_data->>'startsAt','')::timestamptz;v_due:=nullif(p_data->>'dueAt','')::timestamptz;
 IF length(btrim(p_data->>'title')) NOT BETWEEN 2 AND 100 OR length(btrim(p_data->>'description')) NOT BETWEEN 1 AND 1000
 OR length(btrim(p_data->>'objective')) NOT BETWEEN 1 AND 500 OR length(btrim(p_data->>'instructions')) NOT BETWEEN 1 AND 1000
 OR length(btrim(p_data->>'evidenceCriterion')) NOT BETWEEN 1 AND 300 OR length(p_data->>'bibleReference')>100
 OR p_data->>'rewardTier' NOT IN ('normal','great','epic','extraordinary') OR p_data->>'kind' NOT IN ('mission','special')
 OR p_data->>'audience' NOT IN ('all','selected') OR (p_data->>'audience'='selected' AND cardinality(v_targets)=0)
 OR (p_data->>'audience'='all' AND cardinality(v_targets)>0) OR (v_start IS NOT NULL AND v_due IS NOT NULL AND v_due<=v_start)
 THEN RAISE EXCEPTION 'Invalid mission data' USING ERRCODE='22023'; END IF;
 IF p_expected_revision=0 THEN
   SELECT gm.guild_id INTO v_guild FROM public.guild_members gm WHERE gm.traveler_id=p_actor AND gm.status='active';
 ELSE SELECT * INTO v_old FROM public.guild_missions WHERE id=p_mission FOR UPDATE;v_guild:=v_old.guild_id; END IF;
 PERFORM guild_ops.actor(p_actor,v_guild,true);
 IF EXISTS(SELECT 1 FROM unnest(v_targets) target WHERE NOT EXISTS(SELECT 1 FROM public.guild_members gm WHERE gm.traveler_id=target AND gm.guild_id=v_guild AND gm.status='active')) THEN RAISE EXCEPTION 'Audience outside guild'; END IF;
 IF p_expected_revision=0 THEN
   -- Client UUID makes repeated create requests idempotent; fingerprint rejects changed payloads.
   INSERT INTO public.guild_missions(id,guild_id,created_by_traveler_id,title,description,mission_type,completion_mode,requires_leader_approval,reward_tier,objective,instructions,evidence_criterion,bible_reference,starts_at,due_at,audience,target_traveler_ids,creation_fingerprint)
   VALUES(p_mission,v_guild,p_actor,btrim(p_data->>'title'),btrim(p_data->>'description'),CASE WHEN p_data->>'kind'='special' THEN 'special_mission' ELSE 'practical_activity' END,'leader_approval',true,p_data->>'rewardTier',btrim(p_data->>'objective'),btrim(p_data->>'instructions'),btrim(p_data->>'evidenceCriterion'),nullif(btrim(p_data->>'bibleReference'),''),v_start,v_due,p_data->>'audience',v_targets,md5(p_data::text)) ON CONFLICT(id) DO NOTHING;
   IF NOT FOUND AND NOT EXISTS(SELECT 1 FROM public.guild_missions WHERE id=p_mission AND created_by_traveler_id=p_actor AND guild_id=v_guild AND creation_fingerprint=md5(p_data::text)) THEN RAISE EXCEPTION 'Mission request conflict'; END IF;
 ELSE
   IF v_old.status<>'draft' OR v_old.workspace_revision<>p_expected_revision THEN RAISE EXCEPTION 'Stale draft'; END IF;
   UPDATE public.guild_missions SET title=btrim(p_data->>'title'),description=btrim(p_data->>'description'),objective=btrim(p_data->>'objective'),instructions=btrim(p_data->>'instructions'),evidence_criterion=btrim(p_data->>'evidenceCriterion'),bible_reference=nullif(btrim(p_data->>'bibleReference'),''),starts_at=v_start,due_at=v_due,reward_tier=p_data->>'rewardTier',mission_type=CASE WHEN p_data->>'kind'='special' THEN 'special_mission' ELSE 'practical_activity' END,audience=p_data->>'audience',target_traveler_ids=v_targets,completion_mode='leader_approval',requires_leader_approval=true,workspace_revision=workspace_revision+1 WHERE id=p_mission;
   INSERT INTO public.guild_activity_log(guild_id,actor_traveler_id,event_type,entity_type,entity_id) VALUES(v_guild,p_actor,'mission_draft_updated','mission',p_mission);
 END IF;
 RETURN p_mission;
END $function$

CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.spend_coins(p_traveler_id uuid, p_amount integer)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  resulting_coins integer;
BEGIN
  IF p_amount <= 0 THEN
    RAISE EXCEPTION 'Amount must be positive' USING ERRCODE = '22023';
  END IF;

  UPDATE public.wallets
  SET coins = coins - p_amount
  WHERE traveler_id = p_traveler_id AND coins >= p_amount
  RETURNING coins INTO resulting_coins;

  IF resulting_coins IS NULL THEN
    RAISE EXCEPTION 'Insufficient balance or wallet not found' USING ERRCODE = 'P0001';
  END IF;

  RETURN resulting_coins;
END;
$function$

CREATE OR REPLACE FUNCTION public.start_guild_mission(p_mission_id uuid, p_traveler_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE progress_id uuid;
BEGIN
  IF NOT public.owns_traveler(p_traveler_id) THEN RAISE EXCEPTION 'Traveler not owned' USING ERRCODE = '42501'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.guild_missions m JOIN public.guild_members gm ON gm.guild_id = m.guild_id WHERE m.id = p_mission_id AND m.status = 'published' AND (m.starts_at IS NULL OR m.starts_at <= now()) AND (m.due_at IS NULL OR m.due_at > now()) AND gm.traveler_id = p_traveler_id AND gm.status = 'active') THEN RAISE EXCEPTION 'Mission unavailable' USING ERRCODE = '42501'; END IF;
  INSERT INTO public.guild_mission_progress(mission_id, traveler_id, status, started_at) VALUES (p_mission_id, p_traveler_id, 'started', now())
  ON CONFLICT (mission_id, traveler_id) DO UPDATE SET status = 'started', started_at = coalesce(public.guild_mission_progress.started_at, now()), submitted_at = NULL WHERE public.guild_mission_progress.status IN ('available','rejected')
  RETURNING id INTO progress_id;
  IF progress_id IS NULL THEN RAISE EXCEPTION 'Mission already submitted or completed' USING ERRCODE = 'P0001'; END IF;
  RETURN progress_id;
END $function$

CREATE OR REPLACE FUNCTION story_private.refresh_progress()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_revision integer; v_steps text[]; v_video boolean; v_reward text;
BEGIN
  -- Same traveler lock as complete_story: concurrent steps/completions serialize.
  PERFORM 1 FROM public.travelers WHERE id = NEW.traveler_id FOR UPDATE;
  IF EXISTS (SELECT 1 FROM public.story_progress WHERE traveler_id=NEW.traveler_id AND story_id=NEW.story_id AND completed_at IS NOT NULL) THEN
    RAISE EXCEPTION 'Story already completed';
  END IF;
  SELECT revision INTO STRICT v_revision FROM public.story_definitions WHERE id=NEW.story_id;
  IF NEW.revision <> v_revision THEN RAISE EXCEPTION 'Stale story revision'; END IF;
  SELECT array_agg(step ORDER BY step), bool_or(step='video'), max(proof_reference) FILTER (WHERE step='reward')
    INTO v_steps,v_video,v_reward FROM story_private.step_receipts
    WHERE traveler_id=NEW.traveler_id AND story_id=NEW.story_id AND revision=v_revision;
  INSERT INTO public.story_progress(traveler_id,story_id,completed_steps,video_completed,reward_receipt)
    VALUES(NEW.traveler_id,NEW.story_id,v_steps,COALESCE(v_video,false),v_reward)
    ON CONFLICT(traveler_id,story_id) DO UPDATE SET completed_steps=EXCLUDED.completed_steps,
      video_completed=EXCLUDED.video_completed,reward_receipt=EXCLUDED.reward_receipt;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.submit_guild_mission(p_mission_id uuid, p_traveler_id uuid, p_completion_note text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE mission_mode text; next_status text;
BEGIN
  IF NOT public.owns_traveler(p_traveler_id) THEN RAISE EXCEPTION 'Traveler not owned' USING ERRCODE = '42501'; END IF;
  IF char_length(coalesce(p_completion_note,'')) > 500 THEN RAISE EXCEPTION 'Completion note too long' USING ERRCODE = '22023'; END IF;
  SELECT m.completion_mode INTO mission_mode FROM public.guild_missions m JOIN public.guild_members gm ON gm.guild_id = m.guild_id WHERE m.id = p_mission_id AND m.status = 'published' AND (m.due_at IS NULL OR m.due_at > now()) AND gm.traveler_id = p_traveler_id AND gm.status = 'active';
  IF mission_mode IS NULL THEN RAISE EXCEPTION 'Mission unavailable' USING ERRCODE = '42501'; END IF;
  next_status := CASE WHEN mission_mode = 'self_complete' THEN 'completed' ELSE 'pending_approval' END;
  UPDATE public.guild_mission_progress SET status = next_status, submitted_at = now(), completion_note = nullif(btrim(coalesce(p_completion_note,'')),''), completed_at = CASE WHEN next_status = 'completed' THEN now() ELSE NULL END WHERE mission_id = p_mission_id AND traveler_id = p_traveler_id AND status = 'started';
  IF NOT FOUND THEN RAISE EXCEPTION 'Mission must be started first' USING ERRCODE = 'P0001'; END IF;
  IF next_status = 'completed' THEN
    PERFORM public.apply_guild_mission_reward(p_mission_id, p_traveler_id);
    UPDATE public.guild_mission_progress SET reward_claimed_at = now() WHERE mission_id = p_mission_id AND traveler_id = p_traveler_id;
  END IF;
  RETURN next_status;
END $function$

CREATE OR REPLACE FUNCTION public.transition_guild_mission_v2(p_actor uuid, p_mission uuid, p_expected_revision integer, p_action text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE m public.guild_missions; v_status text;
BEGIN
 IF p_expected_revision IS NULL OR p_expected_revision<1 THEN RAISE EXCEPTION 'Invalid mission revision'; END IF;
 SELECT * INTO m FROM public.guild_missions WHERE id=p_mission FOR UPDATE;
 PERFORM guild_ops.actor(p_actor,m.guild_id,true);
 v_status:=CASE p_action WHEN 'publish' THEN 'published' WHEN 'close' THEN 'closed' WHEN 'cancel' THEN 'cancelled' END;
 IF v_status IS NULL THEN RAISE EXCEPTION 'Invalid transition'; END IF;
 IF m.status=v_status THEN RETURN; END IF;
 IF m.workspace_revision<>p_expected_revision OR NOT ((m.status='draft' AND p_action IN ('publish','cancel')) OR (m.status='published' AND p_action IN ('close','cancel'))) THEN RAISE EXCEPTION 'Stale mission or invalid transition'; END IF;
 IF p_action='publish' AND (m.objective IS NULL OR m.instructions IS NULL OR m.evidence_criterion IS NULL OR (m.due_at IS NOT NULL AND m.due_at<=clock_timestamp())) THEN RAISE EXCEPTION 'Complete the draft before publication'; END IF;
 UPDATE public.guild_missions SET status=v_status,published_at=CASE WHEN p_action='publish' THEN clock_timestamp() ELSE published_at END,closed_at=CASE WHEN p_action IN ('close','cancel') THEN clock_timestamp() ELSE closed_at END,workspace_revision=workspace_revision+1 WHERE id=p_mission;
 INSERT INTO public.guild_activity_log(guild_id,actor_traveler_id,event_type,entity_type,entity_id,metadata) VALUES(m.guild_id,p_actor,'mission_state_changed','mission',p_mission,jsonb_build_object('action',p_action));
END $function$
